window.CASES=[{"id":"lung-ros1","cancerType":"肺癌","shortTitle":"ROS1 融合肺癌","title":"一例 ROS1 融合肺癌精准治疗临床病例分享","subtitle":"驱动基因阳性晚期肺癌的动态临床决策","doctor":"薛锦慧","hospital":"中山大学附属肿瘤防治中心","difficulty":"进阶","minutes":12,"color":"violet","image":"./assets/cases/lung-ros1-home.png","source":"肺癌 薛锦慧-中山大学附属肿瘤防治中心-一例ROS1融合肺癌精准治疗临床病例分享.pdf","summary":[{"label":"患者画像","value":"女性，50 岁；肺腺癌伴多发脑转移。"},{"label":"初始分子检测","value":"CD74–ROS1 融合阳性；EGFR、ALK、KRAS、BRAF、RET 等阴性。"},{"label":"疾病分期","value":"右肺腺癌 T4N3M1c，IVB 期；颅内与胸内病灶均需全程管理。"},{"label":"核心难点","value":"驱动基因阳性晚期肺癌如何在颅内外病灶、疗效变化与治疗可及性之间安排全程决策。"}],"timeline":[{"date":"2020.12","title":"一线 ROS1 靶向治疗","detail":"塞瑞替尼治疗，最佳疗效 PR，PFS 约 10 个月。"},{"date":"2021.09","title":"颅内进展","detail":"多发脑转移进展，接受全脑放疗并延续原靶向治疗。"},{"date":"2021.12","title":"二线临床研究","detail":"进入 APG-2449 研究，疾病稳定，PFS 约 8 个月。"},{"date":"2022.09","title":"化疗联合抗血管","detail":"培美曲塞、卡铂联合贝伐珠单抗，5 个周期后获得 PR。"},{"date":"2023.08","title":"再活检明确耐药","detail":"检测到 ROS1 D869Y 与 TP53 改变，为后续精准选择提供依据。"},{"date":"2023.09+","title":"新一代选择性 ROS1 抑制剂","detail":"进入 JYP0322 研究并持续获得 PR。"}],"outcomeMedia":{"src":"./assets/cases/lung-treatment-response.png","alt":"肺癌基线及治疗后影像疗效对比","caption":"基线及治疗后影像对比，最佳疗效 PR。"},"questions":[{"id":"lung-ros1-q1","domain":"治疗决策","prompt":"患者确诊 ROS1 融合阳性 IVB 期肺腺癌，伴脑转移，ECOG PS 1 分。综合当前规范，此时最适宜的初始系统治疗策略是？","context":"2020 年初诊时 · 初始治疗","options":["含铂双药化疗联合贝伐珠单抗","免疫检查点抑制剂联合化疗","ROS1 酪氨酸激酶抑制剂（如克唑替尼）","全脑放疗联合最佳支持治疗"],"correctIndex":2,"explanation":"根据 CSCO 非小细胞肺癌诊疗指南 2026，目前 ROS1 融合基因阳性 IV 期 NSCLC 一线治疗 I 级推荐应用克唑替尼，含铂双药化疗±贝伐珠单抗可作为 ROS1 融合阳性非鳞癌患者一线治疗的Ⅱ级推荐。","takeaways":["ROS1 融合阳性 IV 期 NSCLC 一线治疗 I 级推荐应用克唑替尼。"],"evidence":{"sourceTitle":"中国临床肿瘤学会（CSCO）非小细胞肺癌诊疗指南 2026","sourceVersion":"2026","evidenceSummary":"目前 ROS1 融合基因阳性 IV 期 NSCLC 一线治疗 I 级推荐应用克唑替尼，含铂双药化疗±贝伐珠单抗可作为 ROS1 融合阳性非鳞癌患者一线治疗的Ⅱ级推荐。"}},{"id":"lung-ros1-q2","domain":"耐药管理","prompt":"患者在 ROS1 靶向治疗期间出现 CNS 进展，颅外病灶仍相对稳定。下列哪项属于当前正式指南明确列出的 CNS 进展管理路径？","context":"2021 年 9 月 CNS 进展时 · 疾病进展管理","options":["立即停用靶向药，更换为含铂双药化疗","克唑替尼或克唑替尼联合局部治疗","单纯增加原靶向药物剂量","暂停所有抗肿瘤治疗，仅行最佳支持治疗"],"correctIndex":1,"explanation":"根据肺癌中西医结合诊疗指南 2024，ROS1 融合 NSCLC 二线治疗中，对于 CNS 进展，Ⅰ级推荐克唑替尼或克唑替尼 + 局部治疗（限 CNS/寡进展）。","takeaways":["ROS1 融合 NSCLC 发生 CNS 进展时，指南列出克唑替尼或克唑替尼联合局部治疗。"],"evidence":{"sourceTitle":"肺癌中西医结合诊疗指南","sourceVersion":"2024","evidenceSummary":"ROS1 融合 NSCLC 二线治疗，寡进展或 CNS 进展：Ⅰ级推荐克唑替尼或克唑替尼 + 局部治疗（限 CNS/寡进展）。"}},{"id":"lung-ros1-q3","domain":"耐药管理","prompt":"患者经多线 TKI 治疗后出现脑部及肺部广泛进展，再次活检暂不可行且后续 ROS1 抑制剂可及性受限。此时最适宜的系统治疗方案是？","context":"2022 年 8 月广泛进展时 · 后线系统治疗","options":["单药免疫治疗","含铂双药化疗联合或不联合贝伐珠单抗","继续原 TKI 治疗","单纯局部放疗"],"correctIndex":1,"explanation":"根据 CACA 肺癌指南 2024，ROS1 阳性一线治疗后广泛进展，推荐含铂双药化疗 + 局部治疗或含铂双药化疗 + 贝伐珠单抗（非鳞癌）。在 TKI 耐药且无其他靶向药可用时，含铂双药化疗±贝伐珠单抗是标准后线选择。","takeaways":["TKI 耐药广泛进展后，含铂化疗±贝伐珠单抗是标准后线治疗。"],"evidence":{"sourceTitle":"肺癌","sourceVersion":"2024","evidenceSummary":"ROS1 阳性后线治疗：一线治疗后广泛进展，推荐含铂双药化疗 + 局部治疗或含铂双药化疗 + 贝伐珠单抗（非鳞癌）。"}},{"id":"lung-ros1-q4","domain":"耐药管理","prompt":"患者化疗后再次进展，拟重新评估分子状态以指导后续治疗。关于 ROS1 融合基因检测策略，下列说法正确的是？","context":"2023 年 8 月再次进展时 · 分子检测与耐药评估","options":["IHC 检测是 ROS1 融合确诊的金标准，无需其他验证","仅推荐进行血液 NGS 检测，无需组织活检","推荐采用 FISH、qRT-PCR 或 NGS 方法进行检测","ROS1 融合发生率极低，无需常规检测"],"correctIndex":2,"explanation":"根据 CACA 肺癌指南 2024，ROS1 融合基因检测方法包括 FISH、qRT-PCR 和 NGS 方法。其中 qRT-PCR 和 NGS 法获 NMPA 注册证用于肿瘤组织 ROS1 融合基因检测。IHC 仅用于初筛，阳性需验证。ROS1 融合发生率 1%-2%，需规范检测。","takeaways":["ROS1 融合检测推荐 FISH、qRT-PCR 或 NGS，IHC 仅用于初筛。"],"evidence":{"sourceTitle":"肺癌","sourceVersion":"2024","evidenceSummary":"ROS1 融合基因检测方法包括：FISH、qRT-PCR 和 NGS 方法。"}},{"id":"lung-ros1-q5","domain":"耐药管理","prompt":"患者标准后线治疗选择受限，且有意愿探索新治疗选择。关于此时合理的治疗策略，下列说法正确的是？","context":"2023 年 9 月后线治疗时 · 后线治疗与临床研究","options":["仅能接受最佳支持治疗，无其他选择","参加 ROS1 抑制剂临床研究是合理选择之一","必须继续使用原化疗方案，不得更改","仅推荐局部放疗，不考虑系统治疗"],"correctIndex":1,"explanation":"根据 CSCO 非小细胞肺癌诊疗指南 2026，IV 期 ROS1 融合 NSCLC 三线治疗（PS0-2 分）Ⅱ级推荐包括单药化疗 + 贝伐珠单抗（非鳞癌）及参加 ROS1 抑制剂临床研究。在标准治疗受限或患者有意愿探索新治疗时，参加临床研究是合理选择。","takeaways":["ROS1 融合 NSCLC 后线治疗中，参加 ROS1 抑制剂临床研究是指南推荐的合理选择之一。"],"evidence":{"sourceTitle":"中国临床肿瘤学会（CSCO）非小细胞肺癌诊疗指南 2026","sourceVersion":"2026","evidenceSummary":"IV 期 ROS1 融合 NSCLC 三线治疗，PS0-2 分：Ⅰ级推荐单药化疗；Ⅱ级推荐单药化疗 + 贝伐珠单抗（非鳞癌）、参加 ROS1 抑制剂临床研究。"}}],"category":"肺癌","demoOnly":true},{"id":"lung-alk-adenosquamous","cancerType":"肺癌","category":"肺癌","demoOnly":true,"shortTitle":"ALK融合阳性肺腺鳞癌","title":"ALK融合阳性肺腺鳞癌经靶向转化、根治性切除及脑部病灶局部治疗的全程管理","subtitle":"从有限活检与动态分子诊断到术后辅助及中枢神经系统病灶评估","doctor":"","hospital":"","minutes":0,"difficulty":"进阶","color":"violet","image":"./assets/cases/lung-ros1-home.png","imageAlt":"肺癌病例主题图","source":"./assets/cases/lung-alk-adenosquamous.png","contentImages":[],"summary":[{"label":"患者画像","value":"女性，57岁；无吸烟史，ECOG PS 1，因刺激性干咳就诊。"},{"label":"初始诊断","value":"左肺下叶非小细胞肺癌，有限活检倾向鳞癌；临床评估cT2N1M0、ⅡB期，ALK D5F3阴性。"},{"label":"动态病理分子","value":"再次取材确诊腺鳞癌，PCR检出ALK融合；手术标本ALK D5F3阳性、PD-L1 TPS＜1%。"},{"label":"核心难点","value":"有限取材与检测结果差异、阿来替尼转化后的手术机会、术后辅助治疗及新发脑部病灶的分层管理。"}],"timeline":[{"date":"2023.08","title":"初诊与临床分期","detail":"胸部CT示左肺下叶约3.3 cm团块伴肺门淋巴结肿大；有限活检倾向鳞癌，ALK D5F3阴性，临床评估ⅡB期。"},{"date":"2023.10–11","title":"术前免疫联合化疗","detail":"接受白蛋白紫杉醇、卡铂联合帕博利珠单抗2周期，复查显示原发灶增大；术前出现发热和阻塞性肺炎风险，手术暂缓。"},{"date":"2023.12","title":"再次取材与分子重评","detail":"支气管镜解除气道阻塞并再次取材，病理符合腺鳞癌，PCR检测ALK融合阳性。"},{"date":"2023.12–2024.05","title":"阿来替尼转化治疗","detail":"开始阿来替尼治疗后肿块、肺门淋巴结及阻塞性肺不张逐步改善，重新获得根治性切除机会。"},{"date":"2024.05.23","title":"根治性切除","detail":"行胸腔镜左下肺叶切除及肺门、纵隔淋巴结清扫；术后病理为腺鳞癌，淋巴结阴性，材料报告ypT2N0M0、IB期。"},{"date":"2024.12–2025.06","title":"脑部病灶局部治疗与随访","detail":"辅助阿来替尼期间出现约1.1 cm右颞叶强化灶，考虑转移可能性大；接受立体定向放疗并继续原药，后续MRI示病灶及水肿减轻。"}],"questions":[{"id":"lung-alk-adenosquamous-Q1","domain":"治疗决策","prompt":"患者影像学提示肺门淋巴结可疑，但EBUS-TBNA未证实转移。若MDT评估后仍进入手术路径，为提高病理分期准确性，术中最合理的淋巴结处理是？","context":"当前教学复盘：2023年8月初诊时 · 初始临床分期与手术规划","options":["EBUS-TBNA阴性即可省略术中淋巴结评估","仅切除影像学最大的肺门淋巴结","系统性进行纵隔及肺门淋巴结取样或清扫","仅在术后影像提示复发时再评价淋巴结"],"correctIndex":2,"explanation":"阴性的术前针吸结果不能替代手术路径中的规范淋巴结评估。CHEST指南建议，拟切除的临床I至II期NSCLC应系统性进行纵隔及肺门淋巴结取样或清扫，以获得准确的病理分期。该指南版本晚于病例初诊时间，本题用于当前教学复盘。","takeaways":["进入手术路径后仍需系统性完成肺门和纵隔淋巴结评估。"],"reference":{"evidence_type":"指南","doc_id":"e2574d47-8f47-4596-bd57-d10e71895310","split_index":8,"type":"guideline","authority":"CHEST","source_title":"Management of Patients With Early-Stage Non-Small Cell Lung Cancer","source_version":"2025","source_section":"Lymph Node Evaluation","source_url":"","evidence_summary":"指南建议拟切除的临床I至II期NSCLC系统性进行纵隔及肺门淋巴结取样或清扫，以获得准确的病理分期。"},"evidence":{"sourceTitle":"Management of Patients With Early-Stage Non-Small Cell Lung Cancer","sourceVersion":"2025","evidenceSummary":"指南建议拟切除的临床I至II期NSCLC系统性进行纵隔及肺门淋巴结取样或清扫，以获得准确的病理分期。"}},{"id":"lung-alk-adenosquamous-Q2","domain":"治疗决策","prompt":"支气管镜标本组织有限，形态仅倾向鳞癌，TTF-1阴性、P40局灶弱阳性且CK5/6阳性。兼顾组织学分型与后续治疗相关检测，最合理的病理策略是？","context":"当前教学复盘：2023年8月有限活检时 · 初诊有限活检病理评估","options":["追加尽可能完整的免疫组化套餐直至组织耗尽","采用TTF-1、P40等精简标志物完成倾向性分型并保留组织","仅凭CK5/6阳性即可排除腺癌成分并终止分子检测","小活检不能准确分型，因此无需进行任何免疫组化"],"correctIndex":1,"explanation":"有限标本应避免无目的地扩大免疫组化套餐。共识建议根据形态选择精简标志物完成腺癌与鳞癌的倾向性分型，同时保留足够组织用于治疗相关分子检测。该共识版本晚于病例初诊时间，本题用于当前教学复盘。","takeaways":["有限活检应以精简免疫组化兼顾分型和组织保留。"],"reference":{"evidence_type":"指南","doc_id":"3c135c66-a9b5-48a9-8262-e2c3939ca5ac","split_index":7,"type":"guideline","authority":"CACA","source_title":"肺癌小活检标本病理诊断规范专家共识","source_version":"2024","source_section":"（二）肺癌小活检标本诊断规范及推荐术语（表1）","source_url":"","evidence_summary":"共识建议小活检使用精简免疫组化完成倾向性分型，并预留足够组织用于治疗相关分子检测。"},"evidence":{"sourceTitle":"肺癌小活检标本病理诊断规范专家共识","sourceVersion":"2024","evidenceSummary":"共识建议小活检使用精简免疫组化完成倾向性分型，并预留足够组织用于治疗相关分子检测。"}},{"id":"lung-alk-adenosquamous-Q3","domain":"治疗决策","prompt":"患者完成根治性切除，术后病理为ALK融合阳性、ypT2N0M0。结合现有研究结果，术后系统治疗最值得优先讨论的循证方向是？","context":"当前教学复盘：2024年5月根治性切除后 · 根治性切除后辅助治疗","options":["优先讨论阿来替尼辅助治疗","因PD-L1低表达而优先选择免疫单药","因鳞癌成分占优势而必须选择含铂化疗","ALK状态仅影响晚期治疗，术后只能观察"],"correctIndex":0,"explanation":"ALINA是一项比较辅助阿来替尼与含铂化疗的Ⅲ期随机研究，结果显示阿来替尼显著改善完全切除的IB至IIIA期ALK阳性NSCLC患者的DFS。本患者既往接受过术前免疫化疗及阿来替尼转化治疗，与ALINA典型研究路径并不完全相同，因此应将该结果作为重要依据，由MDT结合既往治疗个体化讨论，而不能机械外推。","takeaways":["ALINA支持术后阿来替尼的DFS获益，但复杂既往治疗路径仍需评估证据适用边界。"],"reference":{"evidence_type":"临床研究","doc_id":"c5fdc15964026728bfb3b575037c5588","split_index":1,"type":"meeting","authority":"ESMO","source_title":"LBA2 - ALINA: Efficacy and safety of adjuvant alectinib versus chemotherapy in patients with early-stage ALK+ non-small cell lung cancer (NSCLC)","source_version":"2023","source_section":"LBA2 - ALINA: Efficacy and safety of adjuvant alectinib versus chemotherapy in patients with early-stage ALK+ non-small cell lung cancer (NSCLC)","source_url":"https://cslide.ctimeetingtech.com/esmo2023/attendee/confcal/show/session/65","evidence_summary":"ALINA研究显示，辅助阿来替尼较含铂化疗显著改善完全切除的IB至IIIA期ALK阳性NSCLC患者DFS。"},"evidence":{"sourceTitle":"LBA2 - ALINA: Efficacy and safety of adjuvant alectinib versus chemotherapy in patients with early-stage ALK+ non-small cell lung cancer (NSCLC)","sourceVersion":"2023","evidenceSummary":"ALINA研究显示，辅助阿来替尼较含铂化疗显著改善完全切除的IB至IIIA期ALK阳性NSCLC患者DFS。"}},{"id":"lung-alk-adenosquamous-Q4","domain":"治疗决策","prompt":"阿来替尼期间MRI发现新发单个脑部强化灶，考虑转移可能，但同期全身复查尚未完成。在定义为CNS寡进展并决定继续或更换ALK-TKI前，最合理的下一步是？","context":"当前教学复盘：2024年12月发现脑部强化灶时 · 辅助靶向治疗期间新发脑部病灶评估","options":["立即定义为寡进展并永久维持原方案","仅凭单个脑灶立即更换为另一种ALK-TKI","完善全身复评并经MDT确认进展范围，同时评估脑灶局部处理紧迫性","等待出现多个脑转移后再进行任何评估"],"correctIndex":2,"explanation":"指南对寡进展或CNS进展与广泛进展采用不同治疗路径。当前尚缺颅外疾病状态，不能提前定义寡进展；应先明确进展范围，同时根据神经症状和脑部病灶风险判断局部治疗紧迫性。该指南版本晚于病例事件时间，本题用于当前教学复盘。","takeaways":["全身状态未知时不得提前定义寡进展或直接决定继续、停用或更换ALK-TKI。"],"reference":{"evidence_type":"指南","doc_id":"065ff4dc-ec1b-442e-8381-e8d820673576","split_index":181,"type":"guideline","authority":"CSCO","source_title":"中国临床肿瘤学会（CSCO）非小细胞肺癌诊疗指南 2026","source_version":"2026","source_section":"【注释】","source_url":"","evidence_summary":"指南区分ALK-TKI治疗后的寡进展、CNS进展和广泛进展，并针对不同进展范围列出不同治疗策略。"},"evidence":{"sourceTitle":"中国临床肿瘤学会（CSCO）非小细胞肺癌诊疗指南 2026","sourceVersion":"2026","evidenceSummary":"指南区分ALK-TKI治疗后的寡进展、CNS进展和广泛进展，并针对不同进展范围列出不同治疗策略。"}},{"id":"lung-alk-adenosquamous-Q5","domain":"治疗决策","prompt":"假设后续复评确认该病灶为单发、小体积脑转移，且不存在需要立即处理的其他颅内病灶。兼顾局部控制和正常脑组织保护，优先考虑的局部治疗是？","context":"当前教学复盘：假设完成全身复评并确认单发脑转移后 · 脑部病灶局部治疗选择","options":["不论病灶大小均必须开颅切除","直接采用全脑放疗替代局灶治疗","因阿来替尼具有中枢活性而完全取消局部治疗","采用立体定向放射外科或立体定向放疗"],"correctIndex":3,"explanation":"对于单发、小体积脑转移，指南指出SRS可获得较好的局部控制，并减少对周围正常脑组织的损伤。系统治疗继续或更换仍应依据完整全身复评、既往治疗和耐药评估另行判断。","takeaways":["单发小体积脑转移可优先考虑SRS或SRT，系统治疗策略需另行综合判断。"],"reference":{"evidence_type":"指南","doc_id":"1d434dbf-f181-4997-a088-b6de8327c537","split_index":34,"type":"guideline","authority":"中国医师协会肿瘤医师分会","source_title":"肺癌脑转移中国治疗指南（2021年版）","source_version":"2021","source_section":"（四）内科治疗","source_url":"","evidence_summary":"指南指出脑转移瘤体积越小，采用SRS可获得更好的局部控制，并减少对周围脑组织的损伤。"},"evidence":{"sourceTitle":"肺癌脑转移中国治疗指南（2021年版）","sourceVersion":"2021","evidenceSummary":"指南指出脑转移瘤体积越小，采用SRS可获得更好的局部控制，并减少对周围脑组织的损伤。"}}]},{"id":"gastric-her2","cancerType":"胃癌","shortTitle":"HER2 过表达胃癌","title":"一例 HER2 过表达进展期胃癌全程治疗管理病例分享","subtitle":"HER2 阳性进展期胃癌的全程临床决策","doctor":"钱焱","hospital":"中山大学附属第一医院","difficulty":"进阶","minutes":11,"color":"rose","image":"./assets/cases/gastric-her2.png","source":"胃癌 钱焱-中山大学附属第一医院一例HER2过表达进展期胃癌全程治疗管理病例分享.pdf","summary":[{"label":"患者画像","value":"男性，65 岁；ECOG 1，胸骨后疼痛半年余。"},{"label":"病理分子","value":"胃低分化腺癌；HER2 IHC 3+、FISH 阳性，MSS/pMMR，PD-L1 CPS 5。"},{"label":"疾病分期","value":"Borrmann IV 型，cT4N3M1，IV 期，腹膜后淋巴结转移。"},{"label":"核心难点","value":"HER2 阳性进展期胃癌如何整合分子分型、全身治疗、局部机会与安全性管理。"}],"timeline":[{"date":"2022.08","title":"分子分型与 MDT","detail":"HER2 过表达、PD-L1 CPS 5；判断为潜在可切除的局限转移。"},{"date":"2022.08–10","title":"新辅助/转化治疗","detail":"SOX + 曲妥珠单抗 + 帕博利珠单抗 3 周期，疗效 PR。"},{"date":"2022.10.20","title":"根治性手术","detail":"全胃切除联合腹主动脉旁淋巴结清扫。"},{"date":"术后病理","title":"显著病理缓解","detail":"TRG 1，0/80 淋巴结转移，ypT1bN0M0，I 期。"},{"date":"2023.01–05","title":"免疫相关不良反应","detail":"先后出现免疫相关糖尿病/酮症酸中毒与间质性肺炎，暂停抗肿瘤治疗并处理。"},{"date":"2025.06","title":"门诊随访","detail":"增强 CT 未见复发转移，肿瘤标志物未见异常升高。"}],"questions":[{"id":"gastric-her2-q1","domain":"治疗决策","prompt":"65 岁男性，IV 期胃低分化腺癌，HER2 IHC 3+ 且 FISH 扩增，PD-L1 CPS 5，MSS/pMMR，ECOG PS 1。按当前指南进行教学复盘，此时最适宜的一线系统治疗策略是？","context":"当前教学复盘：初始治疗决策时 · 初始治疗","options":["帕博利珠单抗联合曲妥珠单抗及含氟尿嘧啶类和铂类化疗","曲妥珠单抗联合含氟尿嘧啶类和铂类化疗","含氟尿嘧啶类和铂类化疗单药","帕博利珠单抗单药治疗"],"correctIndex":0,"explanation":"Ⅲ期研究 KEYNOTE-811 最终分析结果显示，一线曲妥珠单抗联合化疗中加入帕博利珠单抗显著改善 PD-L1 CPS ≥1 人群的 PFS 和 OS，上述“靶免化”模式获批用于治疗 HER2 高表达和 PD-L1 CPS ≥1 的不可切除或转移性食管胃结合部或胃腺癌患者。本病例 HER2 阳性且 CPS 5，符合该治疗人群。","takeaways":["HER2 高表达且 PD-L1 CPS ≥1 的不可切除或转移性胃腺癌患者，一线推荐帕博利珠单抗联合曲妥珠单抗及化疗。"],"evidence":{"sourceTitle":"中国临床肿瘤学会（CSCO）胃癌诊疗指南 2026","sourceVersion":"2026","evidenceSummary":"Ⅲ期研究 KEYNOTE-811 最终分析结果显示，一线曲妥珠单抗联合化疗中加入帕博利珠单抗显著改善 PD-L1 CPS ≥1 人群的 PFS 和 OS，上述“靶免化”模式获批用于治疗 HER2 高表达和 PD-L1 CPS ≥1 的不可切除或转移性食管胃结合部或胃腺癌患者。"}},{"id":"gastric-her2-q2","domain":"分子诊断","prompt":"对于初诊 IV 期胃癌患者，为指导精准治疗分层，按当前共识进行教学复盘，初诊时推荐完善哪些关键分子检测？","context":"当前教学复盘：初诊时 · 初始诊断","options":["PD-L1 蛋白表达（CPS）、MMR/MSI、HER2、Claudin 18.2、EB 病毒等免疫组化及基因检测","仅检测 HER2 状态和 MMR/MSI 状态","仅检测 PD-L1 蛋白表达和 HER2 状态","无需分子检测，直接开始含氟尿嘧啶类和铂类化疗"],"correctIndex":0,"explanation":"IV 期胃癌患者初诊时，推荐完善活检组织的相关免疫组织化学及基因检测，包括 PD-L1 蛋白表达水平、MMR/MSI、HER2、Claudin 18.2、EB 病毒等，以指导精准转化治疗。","takeaways":["IV 期胃癌初诊应进行全面分子病理学评估，包括 PD-L1 CPS、MMR/MSI、HER2、Claudin 18.2、EB 病毒等。"],"evidence":{"sourceTitle":"精准外科胃癌转化治疗专家共识（2025 版）","sourceVersion":"2025","evidenceSummary":"推荐意见 7：IV 期胃癌患者初诊时，推荐完善活检组织的相关免疫组织化学及基因检测（PD-L1 蛋白表达水平、MMR/MSI、HER2、Claudin 18.2、EB 病毒等）。"}},{"id":"gastric-her2-q3","domain":"治疗决策","prompt":"患者接受 SOX 联合曲妥珠单抗和帕博利珠单抗治疗 3 周期后，增强 CT 提示原发灶及淋巴结明显缩小，评价 PR。依据当前共识进行教学复盘，此时关于手术决策的说法正确的是？","context":"当前教学复盘：转化治疗 3 周期后评估 PR 时 · 转化治疗后评估","options":["不能仅凭影像学缓解直接手术，应重新进入 MDT 评估经综合治疗后是否可能实施根治性手术切除","影像学评价 PR 后即可直接进行手术切除，无需再次评估","必须继续原方案治疗至 6 周期后才可评估手术机会","IV 期胃癌无论治疗反应如何均不应考虑手术，直接改为姑息治疗"],"correctIndex":0,"explanation":"对于初诊评估为 cIV 期胃癌患者，经过 MDT 讨论，认为经综合治疗后有可能实施根治性手术切除者，可实施转化治疗。影像学缓解不等同于适合手术，需 MDT 综合评估转移范围、治疗反应、体能状态、手术风险和 R0 切除可能性后决策。","takeaways":["cIV 期胃癌转化治疗后需经 MDT 综合评估制订后续治疗方案，判断是否可能实施根治性手术切除，而非仅凭影像学缓解直接决策。"],"evidence":{"sourceTitle":"精准外科胃癌转化治疗专家共识（2025 版）","sourceVersion":"2025","evidenceSummary":"推荐意见 2：对于初诊评估为 cⅣ期胃癌患者，经过 MDT 讨论，认为经综合治疗后有可能实施根治性手术切除者，可实施转化治疗。"}},{"id":"gastric-her2-q4","domain":"不良反应","prompt":"患者出现 G4 免疫检查点抑制剂相关 1 型糖尿病并糖尿病酮症酸中毒，血糖>27.8mmol/L，酮体阳性。按当前指南进行教学复盘，此时最恰当的处理是？","context":"出现 G4 ICI 相关 1 型糖尿病并 DKA 时 · 不良反应处理","options":["暂停免疫检查点抑制剂治疗，住院治疗，请内分泌科会诊，起始胰岛素治疗并按 DKA 管理","暂停免疫治疗，口服降糖药控制血糖","继续免疫治疗，同时使用胰岛素","暂停免疫治疗，使用大剂量糖皮质激素治疗糖尿病"],"correctIndex":0,"explanation":"患者出现严重高血糖或 DKA 时应住院，免疫检查点抑制剂应暂停直至 DKA 解决，并起始胰岛素治疗。G4 DKA 需胰岛素而非口服降糖药；G4 毒性需暂停 ICI 而非继续。","takeaways":["G4 ICI 相关高血糖并 DKA 需暂停 ICI、住院、内分泌会诊、起始胰岛素治疗并按 DKA 规范管理。"],"evidence":{"sourceTitle":"Society for Immunotherapy of Cancer (SITC) clinical practice guideline on immune checkpoint inhibitor-related adverse events","sourceVersion":"2021","evidenceSummary":"Patients with new-onset diabetes (type I) should be tested for hemoglobin A1c, C-peptide, autoantibodies and counseled on diabetes management, including diet and lifestyle changes, glucose monitoring, and insulin treatment."}},{"id":"gastric-her2-q5","domain":"不良反应","prompt":"患者出现 G3 免疫检查点抑制剂相关间质性肺炎，伴高热和低氧。支气管肺泡灌洗液涂片曾见革兰阴性杆菌，感染不能排除。此时最恰当的处理是？","context":"依据当前 2026 版共识进行教学复盘：出现 G3 ICI 相关间质性肺炎，感染不能排除时 · 不良反应处理","options":["暂停免疫检查点抑制剂，加强监护，给予甲泼尼龙 500-1000mg/d，同步完善抗感染与并发症处置，由 MDT 共同决策","暂停免疫治疗，给予甲泼尼龙治疗，无需抗感染","继续免疫治疗，同时给予抗感染和激素治疗","永久停用免疫检查点抑制剂，无需激素治疗"],"correctIndex":0,"explanation":"评估为 G3 免疫相关性肺炎时，需暂停 ICI 并加强监护，甲强龙 500~1000mg/d，并同步完善抗感染与并发症处置；整个过程建议由外科、肿瘤内科、呼吸科与影像等 MDT 共同决策，既避免将免疫毒性误判为感染而延误激素治疗，也避免在活动性感染未排除时过早使用免疫抑制剂。本病例感染不能排除，需同时考虑常规感染和免疫相关性肺炎两种可能，积极进行鉴别诊断和并行处理。","takeaways":["G3 ICI 相关肺炎需暂停 ICI、激素治疗、同步抗感染与并发症处置，感染不能排除时需并行鉴别和处理，由 MDT 共同决策。"],"evidence":{"sourceTitle":"消化道肿瘤围手术期免疫治疗相关不良事件管理专家共识（2026 版）","sourceVersion":"2026","evidenceSummary":"评估为 G3 免疫相关性肺炎时，需暂停 ICI 并加强监护，甲强龙 500~1000mg/d，并同步完善抗感染与并发症处置；整个过程建议由外科、肿瘤内科、呼吸科与影像等 MDT 共同决策，既避免将免疫毒性误判为感染而延误激素治疗，也避免在活动性感染未排除时过早使用免疫抑制剂。"}}],"category":"胃癌","demoOnly":true},{"id":"CASE-66FC4AA7","cancerType":"胃癌","category":"胃癌","demoOnly":true,"shortTitle":"胃癌免疫治疗后的胆管损伤与随访","title":"胃癌免疫治疗后的胆管损伤与随访","subtitle":"从MSI检测与疗效判定，到胆管炎鉴别、治疗反应及长期随访","doctor":"","hospital":"","minutes":0,"difficulty":"进阶","color":"violet","image":"./assets/cases/gastric-her2.png","imageAlt":"胃癌病例主题图","source":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/RLUAPlHaLlg4hx2KkHIZoA/9SJytfzLpj0Y0PNuVgm0Y0xn8I2KdL3q.png","contentImages":[{"src":"./assets/case-content/CASE-66FC4AA7.png","alt":"图 1. 腹腔镜远端胃切除术后六个月的轴向腹部增强 CT，胰腺前方可见肿大淋巴结（箭头）。","sourceUrl":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/RLUAPlHaLlg4hx2KkHIZoA/9SJytfzLpj0Y0PNuVgm0Y0xn8I2KdL3q.png"}],"summary":[{"label":"患者画像","value":"男性，67岁；胃腺癌术后约6个月出现淋巴结复发，肿瘤标志物未见明显升高。"},{"label":"病理与分子","value":"材料记载原胃癌T3N3aM0、HER2阴性、MSI-H；分期前缀及MSI检测方法未完整提供，不补写为已证实的临床分期或MMR免疫组化结果。"},{"label":"主要病程","value":"接受帕博利珠单抗后淋巴结明显缩小；第15疗程后出现黄疸及胆汁淤积型肝胆异常，结合影像、内镜及病理诊断免疫相关硬化性胆管炎。"},{"label":"随访与难点","value":"激素调整后改善，约8个月随访仍有胆管扩张；需区分肿瘤控制、炎症活动和残留结构异常。"}],"timeline":[{"date":"初始治疗","title":"胃癌手术及辅助治疗","detail":"接受腹腔镜远端胃切除及辅助化疗；材料记录T3N3aM0，未完整列出分期前缀及版本。"},{"date":"术后约6个月","title":"淋巴结复发","detail":"发现淋巴结复发，肿瘤标志物正常；病例记载MSI-H、HER2阴性，原始检测方法需核对。"},{"date":"复发后","title":"开始免疫治疗","detail":"给予帕博利珠单抗200 mg，每3周一次。"},{"date":"第4疗程后","title":"影像部分缓解","detail":"复查显示淋巴结缩小，病例报告部分缓解。"},{"date":"第13疗程后","title":"淋巴结几乎消失","detail":"CT描述复发淋巴结几乎完全消失；摘要未提供完整RECIST测量，不据此补写正式完全缓解。"},{"date":"第15疗程后","title":"胆汁淤积型异常","detail":"出现乏力、发热、黄疸，ALP/GGT显著升高，转氨酶轻度升高。"},{"date":"肝胆评估阶段","title":"胆道影像与病理","detail":"CT及ERCP显示胆道异常，包括胆总管扩张和远端狭窄，未证实明确机械性梗阻；活检见胆管炎症与结构损伤，诊断免疫相关硬化性胆管炎。"},{"date":"确诊后","title":"激素调整与反应","detail":"氢化可的松减量后病情反复，调整为泼尼松龙后改善；个案不能区分药物、剂量及减量速度的独立作用。"},{"date":"胆管炎发生约8个月后","title":"持续随访","detail":"临床状况良好，激素逐渐减量，肿瘤仍获控制；胆管壁改变减轻，但胆总管扩张仍存在。"}],"questions":[{"id":"CASE-66FC4AA7-Q1","domain":"分子诊断","prompt":"67岁男性，胃癌术后复发，病例记载HER2阴性、MSI-H，随后接受帕博利珠单抗。为核对这一用药依据，需追溯原始分子报告。关于MSI与MMR检测，哪项表述最准确？","context":"当前教学复盘：复发后的免疫治疗评估 · 复发后的免疫治疗评估","options":["免疫组化评估MMR蛋白，PCR评估微卫星不稳定性","免疫组化评估微卫星位点，PCR评估MMR蛋白表达","免疫组化保留表达可判MSI-H，PCR用于补充定量","免疫组化缺失表达可判MSS，PCR用于确定原发灶"],"correctIndex":0,"explanation":"MMR免疫组化检测的是错配修复蛋白表达；MSI-PCR检测的是微卫星位点的不稳定性。两者相关，但并非同一检测。应核对方法、质控及原始结论，不能将病例中的“MSI-H”改写为某次已完成的MMR免疫组化结果。","takeaways":["分清检测对象，并保留原始报告的证据边界。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"CAP","source_title":"CAP：MMR/MSI检测指南（2022）","source_version":"2022","source_section":"","source_url":"https://www.cap.org/cap-guidelines/mismatch-repair-and-microsatellite-instability-testing-for-immune-checkpoint-inhibitor-therapy/","evidence_summary":"分清检测对象，并保留原始报告的证据边界。"},"evidence":{"sourceTitle":"CAP：MMR/MSI检测指南（2022）","sourceVersion":"2022","evidenceSummary":"分清检测对象，并保留原始报告的证据边界。"}},{"id":"CASE-66FC4AA7-Q2","domain":"疗效评估","prompt":"患者治疗13个疗程后，CT描述复发淋巴结“几乎完全消失”。现有摘要未列出各淋巴结短径及全部病灶评估结果。若要按RECIST 1.1正式登记为完全缓解，最需要核对什么？","context":"当前教学复盘：帕博利珠单抗治疗13个疗程后 · 帕博利珠单抗治疗13个疗程后","options":["病灶长径缩小比例，以及同期肿瘤标志物是否正常","最大淋巴结是否消失，以及临床症状是否完全缓解","各病理性淋巴结短径，以及其他病灶和新病灶情况","既往最佳疗效类别，以及本次是否已达到治疗年限"],"correctIndex":2,"explanation":"“几乎消失”不是可直接登记的RECIST类别。完全缓解要求病理性淋巴结短径降至10 mm以下，并满足其他病灶及新病灶的整体评估条件。临床改善或标志物正常不能替代这些要求，影像缓解也不等同于病理完全缓解。","takeaways":["疗效类别由完整测量与全病灶评估确定，而非描述性措辞。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"RECIST工作组","source_title":"RECIST工作组：RECIST 1.1及淋巴结评估","source_version":"RECIST 1.1","source_section":"","source_url":"https://recist.eortc.org/recist-1-1/","evidence_summary":"疗效类别由完整测量与全病灶评估确定，而非描述性措辞。"},"evidence":{"sourceTitle":"RECIST工作组：RECIST 1.1及淋巴结评估","sourceVersion":"RECIST 1.1","evidenceSummary":"疗效类别由完整测量与全病灶评估确定，而非描述性措辞。"}},{"id":"CASE-66FC4AA7-Q3","domain":"不良反应","prompt":"患者出现乏力、发热、黄疸，ALP和GGT明显升高，转氨酶仅轻度升高；CT见胆管扩张、胆囊壁增厚，未显示明确梗阻。在同步排查感染等病因时，为进一步评价胆管损伤，最有针对性的影像检查是？","context":"当前教学复盘：帕博利珠单抗治疗15个疗程后 · 帕博利珠单抗治疗15个疗程后","options":["行肝胆超声联合弹性成像，重点评价肝纤维化程度","行肝胆MRI联合MRCP，重点评价胆管壁与狭窄","行腹部CT血管成像检查，重点评价门静脉血流受阻","行全身PET-CT复查，重点评价胆管周围代谢变化"],"correctIndex":1,"explanation":"这一组合提示胆汁淤积型损伤，MRI联合MRCP有助于评价胆管扩张、狭窄及管壁改变。CT未显示明确梗阻并不等于病因已确定；仍需结合感染检查、其他药物史及必要的内镜或病理评估，鉴别免疫相关胆管炎。","takeaways":["按肝胆损伤模式选择检查，不能凭免疫用药史直接定因。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"中国专家共识","source_title":"中国专家共识：MRI评价腹部免疫相关不良反应（2024），胆管炎部分","source_version":"2024","source_section":"","source_url":"https://doi.org/10.12015/issn.1674-8034.2024.12.004","evidence_summary":"按肝胆损伤模式选择检查，不能凭免疫用药史直接定因。"},"evidence":{"sourceTitle":"中国专家共识：MRI评价腹部免疫相关不良反应（2024），胆管炎部分","sourceVersion":"2024","evidenceSummary":"按肝胆损伤模式选择检查，不能凭免疫用药史直接定因。"}},{"id":"CASE-66FC4AA7-Q4","domain":"治疗决策","prompt":"本例在氢化可的松减量后病情反复，调整为泼尼松龙后改善。讨论其他类似患者时，如何解释这一个案观察最严谨？","context":"当前教学复盘：确诊免疫相关硬化性胆管炎后的治疗复盘 · 确诊免疫相关硬化性胆管炎后的治疗复盘","options":["改善提示泼尼松龙疗效更强，可优先替代同类激素","反复提示病因判断存在偏差，应重新归类为肿瘤进展","改善提示胆管结构已经恢复，可据此缩短后续监测","改善反映整个调整过程获益，尚不能证明药物间优劣"],"correctIndex":3,"explanation":"个案同时涉及药物、等效剂量、减量速度及病程变化，不能分离出某一种激素的比较疗效。胆管型免疫损伤可能对激素反应不充分；再处理需复核感染、梗阻和损伤活动性，由专科团队制定方案，而非复制个案换药顺序。","takeaways":["个案中的时间先后关系，不等于药物优越性的因果证据。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"SITC","source_title":"SITC：免疫检查点抑制剂相关不良反应指南（2021），胆道毒性","source_version":"2021","source_section":"","source_url":"https://jitc.bmj.com/content/9/6/e002435","evidence_summary":"个案中的时间先后关系，不等于药物优越性的因果证据。"},"evidence":{"sourceTitle":"SITC：免疫检查点抑制剂相关不良反应指南（2021），胆道毒性","sourceVersion":"2021","evidenceSummary":"个案中的时间先后关系，不等于药物优越性的因果证据。"}},{"id":"CASE-66FC4AA7-Q5","domain":"随访管理","prompt":"随访时患者临床状况良好，激素逐渐减量，肿瘤未见进展；影像显示胆管壁改变减轻，但胆总管扩张仍存在。对这一残留影像表现，最合适的判断是？","context":"当前教学复盘：免疫相关胆管炎发生约8个月后 · 免疫相关胆管炎发生约8个月后","options":["扩张提示胆道肿瘤性进展，应优先调整抗肿瘤治疗","壁厚减轻提示炎症已消退，可据此结束肝胆随访","结构恢复可能滞后于症状，应结合肝胆指标动态判断","扩张提示免疫损伤仍加重，应按影像程度追加激素"],"correctIndex":2,"explanation":"本例的肿瘤控制与胆道结构异常可以并存。持续扩张本身既不能证明肿瘤进展，也不能单独决定加大免疫抑制。应联合症状、胆红素和胆汁淤积酶谱、感染征象及连续影像，区分残留结构改变与持续活动性损伤。","takeaways":["分别评估肿瘤状态、胆道结构和炎症活动性。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"中国专家共识","source_title":"中国专家共识：MRI评价腹部免疫相关不良反应（2024）＋本例随访事实","source_version":"2024","source_section":"","source_url":"https://doi.org/10.12015/issn.1674-8034.2024.12.004","evidence_summary":"分别评估肿瘤状态、胆道结构和炎症活动性。"},"evidence":{"sourceTitle":"中国专家共识：MRI评价腹部免疫相关不良反应（2024）＋本例随访事实","sourceVersion":"2024","evidenceSummary":"分别评估肿瘤状态、胆道结构和炎症活动性。"}}]},{"id":"CASE-7C34EC3D","cancerType":"乳腺癌","category":"乳腺癌","demoOnly":true,"shortTitle":"乳腺浸润性小叶癌胃肠道与腹膜转移的全程管理","title":"乳腺浸润性小叶癌胃肠道与腹膜转移的全程管理","subtitle":"转移来源鉴别、卵巢抑制、后线证据及腹水与局部治疗边界","doctor":"","hospital":"","minutes":0,"difficulty":"进阶","color":"violet","image":"./assets/cases/breast-cancer-home.png","imageAlt":"乳腺癌病例主题图","source":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/FnzAUsiFez3E1UYv7yJWLw/CHVZxeoHrHV8ipBYwsbR1qtyGvC5Ua1U.png","contentImages":[{"src":"./assets/case-content/CASE-7C34EC3D.png","alt":"图 1 胃和直肠病变的内镜图像。A、B 为胃窦部内镜图像，显示多发火山口样溃疡；C-G 为直肠部内镜图像，显示多发火山口样溃疡；H、I 为病变窄带成像放大图像，显示异常微血管。","sourceUrl":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/FnzAUsiFez3E1UYv7yJWLw/CHVZxeoHrHV8ipBYwsbR1qtyGvC5Ua1U.png"}],"summary":[{"label":"患者画像","value":"女性，52岁；2019年左乳浸润性小叶癌术后，原病理pT2N2aM0、Luminal B型。"},{"label":"病理与原发归属","value":"乳腺原发ER/PR阳性、HER2及E-cadherin阴性；胃肠道病灶形态及ER/PR/GATA3等表型支持乳腺来源，不能归入原发胃癌。"},{"label":"主要治疗经过","value":"2023年胃、结直肠转移后使用来曲唑、哌柏西利及戈舍瑞林，后行双侧附件切除；进展后使用氟维司群联合阿贝西利及化疗。"},{"label":"后续进展","value":"腹水恶性细胞及免疫表型支持腹膜转移，后接受引流及腹腔内顺铂，材料随访至2025年4月。"},{"label":"资料边界","value":"既往用药一处记为AI，一处记为托瑞米芬，药物转换顺序不详；绝经评估结果不完整。腹腔治疗未记载加温或减瘤手术，不写为HIPEC。"}],"timeline":[{"date":"2019.01.30","title":"乳腺原发手术","detail":"左乳切除及腋窝淋巴结清扫，病理为浸润性小叶癌pT2N2aM0，ER/PR阳性、HER2/E-cadherin阴性。"},{"date":"2019","title":"术后综合治疗","detail":"接受EC 4周期序贯脂质体紫杉醇4周期及25次放疗；材料记载启动AI，但后文又记既往托瑞米芬，用药衔接未详。"},{"date":"2023.01","title":"胃肠道转移确诊","detail":"因上腹部不适检查，CT未见明确胃肠道病变；内镜见多发溃疡，活检及对照免疫表型支持乳腺癌胃、结直肠转移。"},{"date":"2023.02","title":"内分泌联合靶向治疗","detail":"记录停托瑞米芬，改用来曲唑联合哌柏西利及戈舍瑞林；原材料未完整提供绝经评估。"},{"date":"2023.05","title":"内镜改善","detail":"复查胃肠道溃疡改善，支持治疗有效；未补写正式RECIST类别。"},{"date":"2023.12","title":"双侧附件切除","detail":"行双侧输卵管卵巢切除，病理示低分化腺癌，考虑乳腺癌转移。"},{"date":"2024.08后","title":"进展后调整方案","detail":"内镜提示进展，改用氟维司群联合阿贝西利；具体换药日未详。"},{"date":"2024.12","title":"腹膜转移与腹水评价","detail":"腹胀伴大网膜结节状增厚及腹水；腹水见恶性细胞，ER/PR阳性、HER2阴性，病例据此诊断腹膜转移。"},{"date":"腹膜转移确诊后","title":"后线化疗","detail":"接受卡培他滨联合长春瑞滨。"},{"date":"2025.02—03","title":"腹膜进展与引流","detail":"CT提示腹膜病变进展，随后置管引流腹水，仍检出恶性细胞。"},{"date":"2025.04","title":"腹腔内治疗","detail":"接受腹腔内顺铂，持续随访；材料未报告加温、减瘤手术或可比较的生存获益。"}],"questions":[{"id":"CASE-7C34EC3D-Q1","domain":"治疗决策","prompt":"52岁女性，既往乳腺浸润性小叶癌，现胃及结直肠多发溃疡。活检见低分化癌，ER、PR、GATA3阳性，E-cadherin及HER2阴性，与原乳腺肿瘤特征相符。综合这些信息，哪项判断最合理？","context":"当前教学复盘：2023年1月：胃肠道病灶来源判断 · 2023年1月：胃肠道病灶来源判断","options":["按多发溃疡的解剖部位，分别归入胃癌与结直肠癌","按低分化癌的组织形态，优先归入胃肠道原发癌","按病史及对照病理结果，支持乳腺癌的胃肠道转移","按HER2阴性的检测结果，支持排除乳腺来源转移"],"correctIndex":2,"explanation":"本例来源判断依靠既往小叶癌病史、形态及免疫表型的综合对照，不是凭GATA3或某一项染色单独定论。转移发生在胃肠道，并不改变乳腺原发的归属；原JSON的“胃癌”分类应纠正。","takeaways":["病灶所在器官不等于肿瘤原发器官。"],"reference":{"evidence_type":"病例与临床推理","doc_id":"","split_index":null,"type":"case_reasoning","authority":"NCI","source_title":"Metastatic Breast Cancer","source_version":"2025","source_section":"What is metastatic breast cancer?","source_url":"https://www.cancer.gov/types/breast/stages/metastatic-breast-cancer","evidence_summary":"NCI说明转移灶保留原发肿瘤类型；本例胃肠道来源的具体结论来自已提供的对照病理。"},"evidence":{"sourceTitle":"Metastatic Breast Cancer","sourceVersion":"2025","evidenceSummary":"NCI说明转移灶保留原发肿瘤类型；本例胃肠道来源的具体结论来自已提供的对照病理。"}},{"id":"CASE-7C34EC3D-Q2","domain":"治疗决策","prompt":"患者胃肠道转移后接受来曲唑、哌柏西利和戈舍瑞林。原资料未完整交代绝经评估结果。若患者此时仍有卵巢功能，戈舍瑞林在该组合中的主要作用是什么？","context":"当前教学复盘：2023年2月：来曲唑联合哌柏西利及戈舍瑞林 · 2023年2月：来曲唑联合哌柏西利及戈舍瑞林","options":["抑制卵巢来源的雌激素，使AI治疗具备内分泌条件","阻断肿瘤细胞的雌激素受体，替代AI的抗肿瘤作用","促进卵巢功能在化疗后恢复，维持稳定的激素水平","减少靶向药引起的骨髓抑制，提高CDK4/6抑制强度"],"correctIndex":0,"explanation":"这是明确的条件性问题，并未补造患者激素检测结果。卵巢功能尚存时，芳香化酶抑制剂不能替代卵巢功能抑制；戈舍瑞林用于抑制卵巢功能。不能仅凭52岁或化疗后停经认定永久绝经，也不能认为哌柏西利具有去势作用。","takeaways":["AI应用需核对卵巢功能及抑制条件。"],"reference":{"evidence_type":"官方医学资料","doc_id":"","split_index":null,"type":"education","authority":"NCI","source_title":"Hormone Therapy for Breast Cancer","source_version":"在线版；核对2026-09-04","source_section":"Therapies that block ovarian function; Aromatase inhibitors","source_url":"https://www.cancer.gov/types/breast/treatment/hormone-therapy","evidence_summary":"绝经前使用芳香化酶抑制剂需同时抑制卵巢功能；GnRH激动剂可实现药物性卵巢功能抑制。"},"evidence":{"sourceTitle":"Hormone Therapy for Breast Cancer","sourceVersion":"在线版；核对2026-09-04","evidenceSummary":"绝经前使用芳香化酶抑制剂需同时抑制卵巢功能；GnRH激动剂可实现药物性卵巢功能抑制。"}},{"id":"CASE-7C34EC3D-Q3","domain":"治疗决策","prompt":"来曲唑联合哌柏西利治疗后进展，本例改用氟维司群联合阿贝西利。当前复盘时参考postMONARCH研究，哪项表述最准确？","context":"当前教学复盘：2024年8月进展后的当前教学复盘 · 2024年8月进展后的当前教学复盘","options":["研究比较两种CDK4/6抑制剂，支持阿贝西利直接优效","研究比较该联合方案与化疗，支持联合方案优于化疗","研究比较两种内分泌药物，支持氟维司群单药优效","研究以氟维司群单药为对照，支持特定联合方案获益"],"correctIndex":3,"explanation":"postMONARCH是随机Ⅲ期研究，比较阿贝西利联合氟维司群与安慰剂联合氟维司群，支持所研究人群的PFS获益。它不证明所有CDK4/6抑制剂均可任意跨线互换，也不是与全部后线方案的比较。本文用于当前复盘，不能反称病例当时已依据后来发表的完整结果决策。","takeaways":["方案特异性证据不能扩大为同类药物的普遍结论。"],"reference":{"evidence_type":"临床研究","doc_id":"","split_index":null,"type":"journal","authority":"JCO；postMONARCH研究组","source_title":"Abemaciclib Plus Fulvestrant in Advanced Breast Cancer After Progression on CDK4/6 Inhibition: Results From the Phase III postMONARCH Trial","source_version":"2024在线发表；2025卷期","source_section":"","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11936477/","evidence_summary":"在既往CDK4/6抑制剂联合内分泌治疗后进展的研究人群中，阿贝西利联合氟维司群较对照改善PFS；并非所有同类药物或全部后线方案间的比较。"},"evidence":{"sourceTitle":"Abemaciclib Plus Fulvestrant in Advanced Breast Cancer After Progression on CDK4/6 Inhibition: Results From the Phase III postMONARCH Trial","sourceVersion":"2024在线发表；2025卷期","evidenceSummary":"在既往CDK4/6抑制剂联合内分泌治疗后进展的研究人群中，阿贝西利联合氟维司群较对照改善PFS；并非所有同类药物或全部后线方案间的比较。"}},{"id":"CASE-7C34EC3D-Q4","domain":"耐药管理","prompt":"患者出现腹胀，CT显示大网膜结节状增厚及腹腔积液，影像考虑腹膜转移。此时腹水病理尚未出具。为进一步判断腹水是否为肿瘤性及其来源，哪项检查最有针对性？","context":"当前教学复盘：2024年12月：腹水细胞学结果出具前 · 2024年12月：腹水细胞学结果出具前","options":["复查血清肿瘤标志物，依据升高幅度判定腹水来源","送检腹水细胞学及细胞块，结合免疫表型对照原癌","复查腹部CT并测量腹水量，依据增长速度确定来源","复查血清白蛋白及肝功能，依据低蛋白程度判定转移"],"correctIndex":1,"explanation":"影像提出腹膜转移的怀疑，细胞学及免疫表型可进一步判断恶性性质和来源。此处考查的是已实际实施的腹水送检路径；单纯液量或标志物不能承担来源判定。若送检阴性但仍高度可疑，需复核取材充分性并讨论其他取材，不能由阴性直接排除转移。","takeaways":["将影像怀疑与恶性细胞及来源证据分开确认。"],"reference":{"evidence_type":"病例与临床推理","doc_id":"","split_index":null,"type":"case_reasoning","authority":"NCI","source_title":"Metastatic Breast Cancer","source_version":"2025","source_section":"How is metastatic breast cancer diagnosed?","source_url":"https://www.cancer.gov/types/breast/stages/metastatic-breast-cancer","evidence_summary":"官方资料支持对疑似转移进行病理及生物标志物核实；腹水细胞学及ER/PR/HER2结果的具体证据来自本例，不将通用资料冒充腹水专门指南。"},"evidence":{"sourceTitle":"Metastatic Breast Cancer","sourceVersion":"2025","evidenceSummary":"官方资料支持对疑似转移进行病理及生物标志物核实；腹水细胞学及ER/PR/HER2结果的具体证据来自本例，不将通用资料冒充腹水专门指南。"}},{"id":"CASE-7C34EC3D-Q5","domain":"治疗决策","prompt":"多线治疗后本例腹膜病变进展，接受腹水引流及腹腔内顺铂。病例未记载肿瘤细胞减灭术或加温灌注。将这一经过写入教学结论时，哪项表述最严谨？","context":"当前教学复盘：2025年4月：腹腔内顺铂治疗复盘 · 2025年4月：腹腔内顺铂治疗复盘","options":["应记为个体化局部处理，尚不足以确立通用治疗标准","可归入减瘤术联合热灌注，借用其他癌种的研究结论","可视为晚期乳腺癌标准后线，主要依据给药途径确定","可视为替代系统治疗的依据，主要依据腹水引流效果"],"correctIndex":0,"explanation":"原资料只支持“腹腔内顺铂”这一实际操作，不能改写为CRS联合HIPEC，也未给出可证明生存获益的比较结果。个体的局部处理不等于乳腺癌普遍标准，不能用结直肠癌腹膜转移证据代替；系统治疗与症状管理仍需分别评估。","takeaways":["区分个案操作、术式定义与可推广的比较证据。"],"reference":{"evidence_type":"病例与临床推理","doc_id":"","split_index":null,"type":"case_reasoning","authority":"病例材料；NCI","source_title":"用户提供的乳腺浸润性小叶癌病例；Metastatic Breast Cancer","source_version":"病例随访至2025；NCI 2025","source_section":"","source_url":"https://www.cancer.gov/types/breast/stages/metastatic-breast-cancer","evidence_summary":"病例仅记载引流和腹腔内顺铂，未报告减瘤术或加温灌注。NCI提供转移性乳腺癌综合治疗背景，不直接推荐本例的腹腔顺铂方案。"},"evidence":{"sourceTitle":"用户提供的乳腺浸润性小叶癌病例；Metastatic Breast Cancer","sourceVersion":"病例随访至2025；NCI 2025","evidenceSummary":"病例仅记载引流和腹腔内顺铂，未报告减瘤术或加温灌注。NCI提供转移性乳腺癌综合治疗背景，不直接推荐本例的腹腔顺铂方案。"}}]},{"id":"CASE-91549FC","cancerType":"乳腺癌","category":"乳腺癌","demoOnly":true,"shortTitle":"合并CMT的炎性乳腺癌：多线治疗与动态分型","title":"合并CMT的炎性乳腺癌：多线治疗与动态分型","subtitle":"神经毒性风险、AI使用条件、PIK3CA靶向、药物皮疹及受体变化","doctor":"","hospital":"","minutes":0,"difficulty":"进阶","color":"violet","image":"./assets/cases/breast-cancer-home.png","imageAlt":"乳腺癌病例主题图","source":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/1diW-n_JYISzOYLvehg1og/egcxHHLZBUnZfSt33TKmE9OoxCeR0Co9.png","contentImages":[{"src":"./assets/case-content/CASE-91549FC.png","alt":"图 1 A）（2021 年）MRI 轴位像 ——T1 加权脂肪抑制增强序列（第二期，120 秒）。肿瘤病灶（大小 41×40×56 mm）主要位于右侧乳房前内象限。因患者体位原因，胸廓前部呈扁平状。（B）（2022 年）MRI 轴位像 ——3D 脂肪抑制 T1 加权序列（DIXON 技术）增强扫描。可见左侧乳房皮肤增厚，伴多发斑片状强化区（提示可能为淋巴道转移灶），且乳房中央区域亦存在强化灶。","sourceUrl":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/1diW-n_JYISzOYLvehg1og/egcxHHLZBUnZfSt33TKmE9OoxCeR0Co9.png"}],"summary":[{"label":"患者画像","value":"女性，50岁，初诊绝经前，合并夏科－马里－图思病；母亲45岁患乳腺癌，患者遗传咨询未检出致病性生殖系突变。"},{"label":"初始诊断","value":"2021年右乳炎性乳腺癌，浸润性导管癌II级，cT4dN1M0、IIIB期；ER/PR阳性、HER2 0、Ki-67约50%。"},{"label":"病程与动态分子","value":"2022年出现左乳及右侧瘢痕肿瘤性病变；后检出PIK3CA突变。2024年皮肤再活检HR阴性、HER2 1+，不等于HER2过表达阳性。"},{"label":"核心难点","value":"神经病变合并症下的化疗风险、卵巢抑制状态核实、PIK3CA靶向证据、3级皮疹处理和后线ADC适用性。"},{"label":"资料边界","value":"原记录化疗为2021年3—12月而手术为9月，存在时间冲突；左乳新原发与转移关联未充分厘清。呼吸衰竭原因未明，不能自动归为药物肺炎。"}],"timeline":[{"date":"2021.02","title":"右侧炎性乳腺癌确诊","detail":"右乳红斑、皮肤增厚和橘皮样改变；MRI约41×40×56 mm病灶及腋窝异常，全身CT未见远处转移；活检ER/PR阳性、HER2 0，临床cT4dN1M0。"},{"date":"2021年术前；月份冲突","title":"新辅助化疗及神经监测","detail":"蒽环类4周期序贯多西他赛4周期，神经科协同监测，未报告明显神经不良反应；源材料记为3—12月，与9月手术不一致，未擅改具体日期。"},{"date":"2021.09；据原记录","title":"手术及残留病理","detail":"右乳切除及腋窝清扫，无重建；残余浸润灶9 mm，16枚淋巴结中1枚微转移，ypT1bN1mi。"},{"date":"术后","title":"放疗与内分泌治疗","detail":"右胸壁及区域淋巴结放疗50 Gy/25次，使用他莫昔芬联合LHRH类似物。"},{"date":"2022.08—11","title":"双侧新病灶评价","detail":"左乳皮肤和腋窝病灶活检为导管癌，ER阳性、PR阴性、HER2 0；右侧瘢痕活检亦见肿瘤。材料记录左乳cT4dN2M0，但不足以独立裁定新原发或转移关系。"},{"date":"2022年后续治疗","title":"化疗后进展","detail":"接受脂质体阿霉素联合环磷酰胺4周期，病情进展。"},{"date":"2022.12—2023.06","title":"内分泌联合CDK4/6抑制剂","detail":"阿贝西利联合来曲唑后约6个月皮肤病变进展；该阶段是否继续卵巢抑制未完整记录。"},{"date":"2023","title":"分子检测","detail":"NGS检出PIK3CA突变，TMB约6.17 mut/Mb；材料报告错配修复蛋白表达正常，不据此推定额外免疫适应证。"},{"date":"2023.07—2024.03","title":"卡培他滨治疗","detail":"皮肤症状改善，获益约8个月。"},{"date":"2024.03起","title":"试验治疗与皮疹","detail":"入组接受氟维司群联合阿培利司，两周期出现3级皮疹并停阿培利司；继续氟维司群后进展。具体衔接月份存在重叠，未补造SCAR诊断。"},{"date":"2024.06—09；据原记录","title":"艾立布林阶段","detail":"接受艾立布林，出现胸腔积液及疾病进展。"},{"date":"2024.09—12","title":"再活检与ADC治疗","detail":"皮肤活检HR阴性、HER2 1+、Ki-67约27%；给予戈沙妥珠单抗，3周期后因呼吸衰竭停用，材料未确定呼吸衰竭病因。"},{"date":"2025.04","title":"随访结局","detail":"患者死亡；原材料报告自初诊约4年。"}],"questions":[{"id":"CASE-91549FC-Q1","domain":"不良反应","prompt":"50岁女性，右侧炎性乳腺癌，合并夏科－马里－图思病，拟接受含多西他赛的术前治疗。针对原有周围神经病变，最合理的风险管理安排是？","context":"当前教学复盘：2021年：术前化疗规划 · 2021年：术前化疗规划","options":["按常规剂量先完成全部疗程，再统一评价神经功能","记录感觉运动功能基线，联诊监测并据功能变化调药","以预防性镇痛药为主要保护，减轻症状后维持剂量","以肿瘤缩小幅度判断耐受性，据影像疗效调整监测"],"correctIndex":1,"explanation":"已有遗传性周围神经病变时，应结合治疗获益、神经功能基线及患者意愿评估神经毒性药物的适用性，并动态监测。出现不能耐受的神经症状或功能损害时讨论延迟、减量、替换或停药。本例未出现明显神经不良反应，不能证明同类患者均安全。","takeaways":["功能基线与动态变化共同决定神经毒性风险管理。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"ASCO","source_title":"Prevention and Management of Chemotherapy-Induced Peripheral Neuropathy in Survivors of Adult Cancers: ASCO Guideline Update","source_version":"2020","source_section":"","source_url":"https://ascopubs.org/doi/abs/10.1200/JCO.20.01399","evidence_summary":"有基础神经病变者应评估神经毒性治疗的风险与获益；治疗中出现不可耐受神经病变或功能损害时应讨论调整化疗。"},"evidence":{"sourceTitle":"Prevention and Management of Chemotherapy-Induced Peripheral Neuropathy in Survivors of Adult Cancers: ASCO Guideline Update","sourceVersion":"2020","evidenceSummary":"有基础神经病变者应评估神经毒性治疗的风险与获益；治疗中出现不可耐受神经病变或功能损害时应讨论调整化疗。"}},{"id":"CASE-91549FC-Q2","domain":"治疗决策","prompt":"本例初诊时为绝经前女性，曾使用他莫昔芬联合LHRH类似物。复发后拟改用来曲唑联合阿贝西利，但摘要未说明卵巢抑制是否继续。此时哪项信息最需要核实？","context":"当前教学复盘：2022年12月：拟用来曲唑联合阿贝西利 · 2022年12月：拟用来曲唑联合阿贝西利","options":["近期肿瘤标志物是否下降，据此确认内分泌治疗条件","既往化疗是否已完成，据此确认不再需要卵巢抑制","年龄是否已超过50岁，据此确认已达到永久绝经","当前卵巢功能与抑制状态，据此确认AI的使用条件"],"correctIndex":3,"explanation":"初诊绝经前、既往用过LHRH类似物，并不能证明换方案时仍在充分抑制卵巢功能。应核实用药衔接与当前卵巢状态；如功能尚存，需建立相应抑制条件。本题不补写病例未提供的用药记录，也不把本次方案误称为患者总体的一线治疗。","takeaways":["既往接受过卵巢抑制，不等于当前仍已满足AI用药条件。"],"reference":{"evidence_type":"官方医学资料","doc_id":"","split_index":null,"type":"education","authority":"NCI","source_title":"Hormone Therapy for Breast Cancer","source_version":"在线版；核对2026-09-04","source_section":"Aromatase inhibitors to block estrogen production","source_url":"https://www.cancer.gov/types/breast/treatment/hormone-therapy","evidence_summary":"绝经前应用芳香化酶抑制剂需要卵巢功能抑制；当前使用条件应核实，不能凭年龄或既往短期用药推定。"},"evidence":{"sourceTitle":"Hormone Therapy for Breast Cancer","sourceVersion":"在线版；核对2026-09-04","evidenceSummary":"绝经前应用芳香化酶抑制剂需要卵巢功能抑制；当前使用条件应核实，不能凭年龄或既往短期用药推定。"}},{"id":"CASE-91549FC-Q3","domain":"分子诊断","prompt":"本例此阶段仍为HR阳性、HER2阴性，既往内分泌治疗后进展，NGS检出PIK3CA突变。讨论阿培利司联合氟维司群时，哪项分子与药物对应关系正确？","context":"当前教学复盘：2024年3月：PIK3CA结果与方案匹配 · 2024年3月：PIK3CA结果与方案匹配","options":["PIK3CA突变支持讨论PI3Kα抑制剂，联合内分泌治疗","PIK3CA突变支持讨论HER2抑制剂，联合内分泌治疗","PIK3CA突变支持讨论PARP抑制剂，联合内分泌治疗","PIK3CA突变支持讨论EGFR抑制剂，联合内分泌治疗"],"correctIndex":0,"explanation":"阿培利司为PI3Kα抑制剂，其标签人群包括内分泌治疗后进展的HR阳性、HER2阴性、PIK3CA突变晚期或转移性乳腺癌，联合氟维司群。本例提供了分子匹配线索，但不能据此忽略卵巢状态、既往治疗、耐受性及试验入组条件。","takeaways":["把靶点、药物机制和适用人群逐项对应。"],"reference":{"evidence_type":"药品说明书","doc_id":"","split_index":null,"type":"drug_label","authority":"Novartis；美国处方说明书","source_title":"PIQRAY (alpelisib) US Prescribing Information","source_version":"2024-01","source_section":"1 Indications and Usage; 2.1 Patient Selection","source_url":"https://www.novartis.com/us-en/sites/novartis_us/files/piqray.pdf","evidence_summary":"PIK3CA突变及HR阳性、HER2阴性状态是阿培利司联合氟维司群相应标签的关键条件。"},"evidence":{"sourceTitle":"PIQRAY (alpelisib) US Prescribing Information","sourceVersion":"2024-01","evidenceSummary":"PIK3CA突变及HR阳性、HER2阴性状态是阿培利司联合氟维司群相应标签的关键条件。"}},{"id":"CASE-91549FC-Q4","domain":"不良反应","prompt":"本例接受阿培利司两周期后出现3级皮疹。仅凭这一分级尚不能确定是否属于SJS/TEN等严重皮肤反应。参照该药说明书，当前最合理的处理是什么？","context":"当前教学复盘：2024年：阿培利司治疗后出现3级皮疹 · 2024年：阿培利司治疗后出现3级皮疹","options":["继续原剂量并加用抗组胺药，待下一周期再评价皮疹","先减量并观察皮疹变化，将停药保留至出现黏膜损害","暂停用药并处理皮疹，同步评估是否存在严重皮肤反应","按已确诊TEN永久停药，无需再评估皮疹的具体类型"],"correctIndex":2,"explanation":"按药品说明书，3级皮疹需暂停阿培利司并治疗、评估严重皮肤反应。非SCAR且恢复至不高于1级时可讨论减量恢复；确认SCAR则永久停药。原病例记录停药，未提供SCAR确诊依据，不能补造TEN诊断。","takeaways":["区分暂缓用药、减量复用与永久停药的条件。"],"reference":{"evidence_type":"药品说明书","doc_id":"","split_index":null,"type":"drug_label","authority":"Novartis；美国处方说明书","source_title":"PIQRAY (alpelisib) US Prescribing Information","source_version":"2024-01","source_section":"2.3 Table 2; 5.2 Severe Cutaneous Adverse Reactions","source_url":"https://www.novartis.com/us-en/sites/novartis_us/files/piqray.pdf","evidence_summary":"皮疹处理需按严重程度并排查SCAR；3级暂停，非SCAR改善后可考虑减量，确认SCAR永久停用。"},"evidence":{"sourceTitle":"PIQRAY (alpelisib) US Prescribing Information","sourceVersion":"2024-01","evidenceSummary":"皮疹处理需按严重程度并排查SCAR；3级暂停，非SCAR改善后可考虑减量，确认SCAR永久停用。"}},{"id":"CASE-91549FC-Q5","domain":"耐药管理","prompt":"后线治疗前皮肤活检由既往HR阳性、HER2 0转为HR阴性、HER2 1+。核对标本及检测可靠性后，关于这一结果的治疗含义，哪项解释最准确？","context":"当前教学复盘：2024年9—12月：皮肤再次活检后 · 2024年9—12月：皮肤再次活检后","options":["HER2 1+表示HER2阳性转化，可照搬过表达人群方案","HR阴性表示先前病理不可信，应撤销原有HR阳性诊断","HER2 1+未达到过表达标准，因此所有ADC均不适用","需重新评估内分泌获益，HER2低表达可影响ADC选择"],"correctIndex":3,"explanation":"应对照病史和病理质控理解受体变化，而非把过去的阳性结果自动判错。HER2 1+不等于HER2过表达阳性；特定ADC的适用性还需核对药物、既往治疗及当地标签，不能由评分直接指定全部后线方案。","takeaways":["动态复核生物标志物，区分低表达与HER2阳性。"],"reference":{"evidence_type":"官方医学资料","doc_id":"","split_index":null,"type":"education","authority":"NCI","source_title":"Tests for Breast Cancer Biomarkers","source_version":"2025","source_section":"Breast cancer hormone receptor status; Breast cancer HER2 status","source_url":"https://www.cancer.gov/types/breast/diagnosis/breast-cancer-biomarker-tests","evidence_summary":"激素受体可随病程变化；HER2低表达不等于HER2阳性，但可影响部分靶向治疗选择。"},"evidence":{"sourceTitle":"Tests for Breast Cancer Biomarkers","sourceVersion":"2025","evidenceSummary":"激素受体可随病程变化；HER2低表达不等于HER2阳性，但可影响部分靶向治疗选择。"}}]},{"id":"esophageal-vaccine","cancerType":"食管癌","shortTitle":"新抗原疫苗联合免疫","title":"个体化新抗原疫苗联合免疫治疗在食管鳞癌术后辅助治疗中的疗效与挑战","subtitle":"局部晚期疾病的综合治疗与动态决策","doctor":"陈月云","hospital":"四川大学华西医院","difficulty":"进阶","minutes":13,"color":"cyan","image":"./assets/cases/esophageal-vaccine.png","source":"食管癌 陈月云-四川大学华西医院-—个体化新抗原疫苗联合免疫治疗在食管鳞癌术后辅助治疗中的疗效与挑战：一例神经内分化转化病例报告.pdf","summary":[{"label":"患者画像","value":"男性，60 岁；进行性吞咽困难 3 月余。"},{"label":"初始诊断","value":"胸中下段食管鳞癌，伴锁骨上转移淋巴结，cT4bN0M1，IVB 期。"},{"label":"初始治疗议题","value":"病灶初始不具备直接根治性切除条件，需由 MDT 评估综合治疗目标与后续复评节点。"},{"label":"核心难点","value":"局部晚期食管鳞癌如何设定转化目标，并在疾病变化中动态权衡局部与系统治疗。"}],"timeline":[{"date":"2021.02","title":"诊断与转化治疗","detail":"两周期化疗联合卡瑞利珠单抗后 PR，由不可切除转为可手术。"},{"date":"2021.05","title":"微创食管切除","detail":"术后 ypT3N0M0，II 期，切缘阴性。"},{"date":"2021.07+","title":"术后研究治疗","detail":"帕博利珠单抗联合个体化新抗原疫苗，按计划完成初免与加强。"},{"date":"2022.10","title":"首次寡进展","detail":"锁骨上及上纵隔淋巴结进展，局部放疗后继续联合治疗。"},{"date":"2023.06","title":"再次活检","detail":"复发灶呈食管鳞癌伴神经内分泌分化，Ki-67 约 85%。"},{"date":"2023.07–09","title":"快速进展","detail":"EP 化疗后严重骨髓抑制，随后多器官转移，OS 30.6 个月。"}],"questions":[{"id":"esophageal-vaccine-q1","domain":"治疗决策","prompt":"患者初诊为食管中下段鳞状细胞癌，记录分期cT4bN0M1、IVB期，右侧锁骨上淋巴结考虑转移，ECOG PS 1。下列哪项最符合此时的临床决策思路？","context":"当前教学复盘：初诊cT4bN0M1、IVB期时 · 初始治疗","options":["不经诱导治疗直接行根治性食管癌切除术","由MDT制定以转化为目标的综合治疗方案，治疗后重新评估根治性局部治疗机会","仅处理吞咽困难等局部症状，不进行系统性抗肿瘤治疗","因记录为IVB期，直接进入最佳支持治疗且不再评估"],"correctIndex":1,"explanation":"指南将转化治疗定义为：对因邻近器官侵犯或远处转移而初始无法切除的肿瘤先进行治疗干预，使其获得根治性手术或根治性放化疗机会；转化手术的目标是诱导治疗后实现R0切除。因此，本例的核心不是根据IVB标签机械放弃，也不是跳过诱导治疗直接手术，而是在MDT框架下先行综合治疗，再动态评估是否获得根治性治疗机会。该指南版本晚于病例初诊时间，本题用于当前教学复盘。","takeaways":["初始不可切除或边缘可切除食管癌的关键决策是先实施转化治疗，再根据治疗反应和可切除性评估根治性治疗机会。"],"evidence":{"sourceTitle":"食管癌整合诊治指南（第二版）","sourceVersion":"2024","evidenceSummary":"指南将转化治疗定义为对因邻近器官侵犯或远处转移而初始无法切除的食管癌进行治疗干预，使其获得根治性手术或放化疗机会；转化手术是诱导治疗后争取R0切除的治疗。"}},{"id":"esophageal-vaccine-q2","domain":"疗效评估","prompt":"患者完成2周期转化治疗后症状改善，原发灶及锁骨上淋巴结明显缩小，影像学评价PR。下列关于下一步决策的说法正确的是？","context":"当前教学复盘：完成2周期转化治疗并获得影像学PR时 · 转化治疗后评估","options":["影像学PR已经等同于可切除，应直接安排手术而无需系统复评","必须固定完成6周期治疗后才能进行任何可切除性评估","应在诱导治疗结束后进行增强胸腹CT或PET/CT等复评，确认肿瘤退缩后达到可切除条件再考虑手术","初诊记录为IVB期，因此无论治疗反应如何均不得考虑手术"],"correctIndex":2,"explanation":"指南要求在至少2周期诱导治疗结束后3至4周，以增强胸腹CT或PET/CT等进行疾病评估；只有肿瘤退缩并经评估达到可切除条件时才进入手术。影像学PR是复评的重要信息，但不能单独替代可切除性判断。该指南版本晚于病例治疗时间，本题用于当前教学复盘。","takeaways":["转化治疗后的手术决策必须经过规范影像复评和可切除性判断，影像学缓解本身不等同于已经适合手术。"],"evidence":{"sourceTitle":"食管癌整合诊治指南（第二版）","sourceVersion":"2024","evidenceSummary":"指南建议至少2周期诱导治疗结束后3至4周进行增强胸腹CT或PET/CT等疾病评估；肿瘤退缩且评估可切除时进行手术，并以R0切除为目标。"}},{"id":"esophageal-vaccine-q3","domain":"治疗决策","prompt":"患者在新辅助免疫化疗后接受根治性切除，术后拟参加帕博利珠单抗联合个体化新抗原疫苗的前瞻性探索性IIT。下列对该方案证据定位的说法正确的是？","context":"当前教学复盘：根治性切除后拟定辅助治疗时 · 术后管理","options":["现有共识不能将该联合方案视为标准辅助治疗，应明确其探索性研究属性并充分知情同意","只要术后仍有肿瘤残余，该联合方案就是正式指南推荐的标准治疗","围术期免疫治疗证据尚不完善，说明任何相关临床研究均不应开展","患者后来获得较长无病生存即可反向证明该联合方案适用于所有同类患者"],"correctIndex":0,"explanation":"共识提到的术后辅助免疫治疗推荐对应新辅助放化疗后根治性手术的场景，同时明确食管鳞癌围术期免疫治疗后复发转移模式尚不明确，暂不讨论。因此，不能把该段证据直接外推为新辅助免疫化疗后帕博利珠单抗联合个体化疫苗的标准依据。本例方案应按探索性IIT呈现，不能用单例结局反向证明通用疗效。","takeaways":["证据适用性取决于既往治疗模式和研究场景；探索性IIT必须与正式指南推荐的标准辅助治疗清楚区分。"],"evidence":{"sourceTitle":"食管鳞癌术后随访中国胸外科专家共识","sourceVersion":"2021","evidenceSummary":"共识指出，术后辅助免疫治疗的相关推荐对应新辅助放化疗后根治性手术患者；围术期免疫治疗患者术后复发转移模式尚不明确，本共识暂不讨论。"}},{"id":"esophageal-vaccine-q4","domain":"治疗决策","prompt":"患者术后出现上纵隔及锁骨上淋巴结复发，病例资料尚不足以确认复发灶是否可切除。下列哪项最符合术后局部区域复发的治疗决策框架？","context":"当前教学复盘：术后首次出现上纵隔及锁骨上淋巴结复发时 · 术后复发","options":["无论复发灶是否可切除，均只需延续原系统治疗","无论既往是否接受放疗，均应直接实施同一放疗方案","只要是局部区域复发就必须手术，不再评估手术禁忌或放疗史","先评估复发灶可切除性及复发部位既往放疗情况，再分层选择根治性或挽救性手术、放化疗、放疗或系统治疗"],"correctIndex":3,"explanation":"指南将术后局部区域复发按两个关键变量分层：是否可手术切除，以及复发部位是否既往接受过放疗。不同组合对应根治性或挽救性手术、同步放化疗、系统治疗联合放疗、单纯放疗或系统性药物治疗等不同路径。因此，在资料尚不足以确定可切除性时，不能直接指定唯一局部或全身方案。该指南版本晚于病例复发时间，本题用于当前教学复盘。","takeaways":["术后局部区域复发的管理不是单一路径，必须结合可切除性和既往放疗史进行分层决策。"],"evidence":{"sourceTitle":"中国临床肿瘤学会（CSCO）食管癌诊疗指南 2026","sourceVersion":"2026","evidenceSummary":"指南将术后局部区域复发按是否可手术切除及复发部位既往是否接受放疗分层，并据此选择根治性或挽救性手术、同步放化疗、系统治疗联合放疗、单纯放疗或系统性药物治疗。"}},{"id":"esophageal-vaccine-q5","domain":"耐药管理","prompt":"患者局部放疗后曾获得缓解，随后病灶再次增大且临床行为发生变化。在选择新的后线系统治疗前，下列哪项处理最合理？","context":"当前教学复盘：局部放疗后曾获缓解、随后再次进展且生物学行为改变时 · 再次进展","options":["仅凭影像学进展推定已转化为小细胞癌，并立即按小细胞癌方案治疗","对可及进展病灶进行穿刺活检或其他有创取材，获得新的病理诊断后再制定后线方案","因为既往局部放疗曾有效，应继续原方案且无需重新评估","一次增强CT已经能够替代病理诊断，无需进行任何组织学确认"],"correctIndex":1,"explanation":"术后随访共识建议：影像学等无创检查考虑复发时，应通过EUS、经皮穿刺、淋巴结或浅表肿物活检等有创检查进一步取得病理诊断。对于本例再次进展并出现生物学行为变化的情况，先重新取材有助于确认复发性质和病理表型，避免仅凭影像或临床推测把“鳞癌伴神经内分泌分化”升级为已经证实的纯神经内分泌癌或小细胞癌。","takeaways":["复发或再次进展时若病理性质会影响后线治疗，应尽可能重新获取组织学证据，避免用影像学推测替代病理确认。"],"evidence":{"sourceTitle":"食管鳞癌术后随访中国胸外科专家共识","sourceVersion":"2021","evidenceSummary":"共识建议，影像学等无创检查考虑复发时，可通过EUS、经皮穿刺、淋巴结或浅表肿物活检等有创检查进一步获取病理诊断。"}}],"category":"食管癌","demoOnly":true},{"id":"CASE-2CBF15F6","cancerType":"食管癌","category":"食管癌","demoOnly":true,"shortTitle":"食管鳞癌免疫相关TEN后未手术的长期管理","title":"食管鳞癌免疫相关TEN后未手术的长期管理","subtitle":"可手术性、重症药疹识别、免疫复药边界及器官保存随访","doctor":"","hospital":"","minutes":0,"difficulty":"进阶","color":"violet","image":"./assets/cases/esophageal-vaccine.png","imageAlt":"食管癌病例主题图","source":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/GXJ9HwAE-uPbuVVjaZW8Ag/LKWp5eDeaPEqPwUZM2IwQDuII7LCvYHn.png","contentImages":[{"src":"./assets/case-content/CASE-2CBF15F6.png","alt":"无明确图注，位于胃镜描述后","sourceUrl":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/GXJ9HwAE-uPbuVVjaZW8Ag/LKWp5eDeaPEqPwUZM2IwQDuII7LCvYHn.png"}],"summary":[{"label":"患者画像","value":"女性，73岁；食管中下段低分化鳞状细胞癌，病变距门齿约29–35 cm。"},{"label":"初始评估","value":"PET提示部分淋巴结可疑，左锁骨上淋巴结穿刺阴性；材料不足以独立重建精确TNM分期。"},{"label":"治疗及不良反应","value":"接受试验性新辅助放化疗联合帕博利珠单抗，后确诊免疫相关TEN并合并MRSA感染，经专科治疗改善，未按原计划手术。"},{"label":"长期随访","value":"连续内镜与影像随访至2024年未发现明确复发；食管壁轻度增厚或僵硬仍需监测，不能在无切除标本时认定pCR。"}],"timeline":[{"date":"初诊","title":"食管鳞癌确诊","detail":"内镜病变位于食管中下段，活检为低分化鳞癌；影像见约3.3×1.6 cm局部病变。"},{"date":"初始分期","title":"可疑淋巴结评价","detail":"PET提示锁骨上及贲门旁等淋巴结可疑，左锁骨上取样未证实肿瘤；未补造确定TNM分期。"},{"date":"2020.12起","title":"试验性术前治疗","detail":"接受41.4 Gy/23次放疗，联合白蛋白紫杉醇、卡铂及2次帕博利珠单抗；该联合方案属于本例试验背景。"},{"date":"2021.02下旬","title":"严重皮肤黏膜反应","detail":"广泛皮疹继发疼痛性破溃、唇部溃疡及出血，后诊断免疫相关TEN，合并MRSA感染。"},{"date":"严重反应治疗阶段","title":"毒性处理与手术路径改变","detail":"接受甲泼尼龙、静脉免疫球蛋白及抗感染等治疗后改善，未按原计划行食管切除；不补写原记录不清的抗感染药名。"},{"date":"2021.05.20","title":"局部疗效复评","detail":"PET未见原食管壁明显肿块，仍有代谢摄取，报告考虑治疗后改变；不能单凭PET认定病理完全缓解。"},{"date":"2022.11.07","title":"内镜与取样复查","detail":"食管通畅，黏膜呈白色改变；病理见轻度异型性，考虑反应性改变。"},{"date":"2023.02.10","title":"影像随访","detail":"CT见轻度壁厚及狭窄，较前改善。"},{"date":"2024.03","title":"持续器官保存随访","detail":"CT仍见轻度壁厚及狭窄；内镜见黏膜完整、管壁较僵硬且蠕动欠佳，未报告明确复发。"}],"questions":[{"id":"CASE-2CBF15F6-Q1","domain":"治疗决策","prompt":"患者73岁，诊断食管中下段鳞状细胞癌，MDT拟评估新辅助治疗后手术路径。在解剖学可切除性之外，哪一组信息最直接影响能否耐受食管切除术？","context":"当前教学复盘：初始治疗规划：73岁、食管中下段鳞癌 · 初始治疗规划：73岁、食管中下段鳞癌","options":["病灶代谢强度、原发灶长度及区域淋巴结的数量","病理分化程度、鳞癌标志物及原发灶免疫组化结果","心肺功能储备、营养与衰弱状态及重要脏器合并症","治疗后缓解深度、随访时间及肿瘤标志物下降幅度"],"correctIndex":2,"explanation":"可切除性回答肿瘤能否切除，可手术性还要回答患者能否承受手术。老年患者需综合功能储备、营养、衰弱及合并症评估；年龄本身不能单独作否定依据。治疗后疗效尚未发生，也不能倒推为初始时点已知信息。","takeaways":["解剖学可切除与患者生理可耐受是两个独立维度。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"Onkopedia / DGHO","source_title":"Onkopedia：食管癌指南（2024），可手术性评估","source_version":"2024；存档版本","source_section":"","source_url":"https://www.onkopedia-guidelines.info/en/onkopedia/archive/guidelines/esophageal-cancer/version-02122025T174721/%40%40guideline/html/index.html","evidence_summary":"解剖学可切除与患者生理可耐受是两个独立维度。"},"evidence":{"sourceTitle":"Onkopedia：食管癌指南（2024），可手术性评估","sourceVersion":"2024；存档版本","evidenceSummary":"解剖学可切除与患者生理可耐受是两个独立维度。"}},{"id":"CASE-2CBF15F6-Q2","domain":"不良反应","prompt":"患者出现广泛红色丘疹，继而发生疼痛性皮肤破溃及唇部溃疡、出血结痂，此时尚未完成皮肤专科诊断。下一步最合适的处置是？","context":"当前教学复盘：2021年2月：放化疗联合帕博利珠单抗后 · 2021年2月：放化疗联合帕博利珠单抗后","options":["暂停免疫用药，紧急评估重症药疹并请皮肤科会诊","先用局部激素，待皮损面积进一步扩大再升级评估","先完成常规抗感染疗程，再判断是否需要皮肤活检","调整为较低免疫剂量，再根据黏膜恢复情况复查"],"correctIndex":0,"explanation":"皮肤疼痛、破溃及黏膜受累是严重皮肤不良反应的警示信号，不能按普通轻度皮疹处理。应暂停可疑免疫药并紧急进行专科评估，视情况住院、活检和排查感染或其他致病药物；不应等待面积继续扩大才启动处置。","takeaways":["识别重症药疹红旗，诊断未定不等于可以延迟处理。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"Cancer Care Ontario","source_title":"Cancer Care Ontario：免疫检查点抑制剂毒性管理指南，皮肤毒性","source_version":"在线版","source_section":"","source_url":"https://www.cancercareontario.ca/en/file/39391/download?token=Thzk5Jp9","evidence_summary":"识别重症药疹红旗，诊断未定不等于可以延迟处理。"},"evidence":{"sourceTitle":"Cancer Care Ontario：免疫检查点抑制剂毒性管理指南，皮肤毒性","sourceVersion":"在线版","evidenceSummary":"识别重症药疹红旗，诊断未定不等于可以延迟处理。"}},{"id":"CASE-2CBF15F6-Q3","domain":"治疗决策","prompt":"后续明确诊断为帕博利珠单抗相关中毒性表皮坏死松解症（TEN），同时合并MRSA感染；经治疗后皮肤改善。关于后续PD-1治疗，哪项原则最合适？","context":"当前教学复盘：确诊免疫相关TEN并接受治疗后 · 确诊免疫相关TEN并接受治疗后","options":["皮肤恢复至轻度后，可在小剂量激素保护下恢复原药","感染获得控制后，可更换另一种PD-1抑制剂再挑战","肿瘤仍存在残留时，可缩短疗程重新引入同类治疗","应永久停用致病免疫药，后续不常规安排同类再挑战"],"correctIndex":3,"explanation":"已确认免疫相关TEN属于危及生命的严重皮肤毒性，不能套用普通可逆性皮疹的复药规则。感染需要同步治疗，但感染控制并不消除再次免疫暴露的风险。后续抗肿瘤治疗应由MDT重新规划，而非根据肿瘤缩小或皮肤好转直接复药。","takeaways":["复药决策取决于毒性类型及严重性，不只是症状是否消退。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"ASCO","source_title":"ASCO：免疫相关不良反应管理指南（2018），严重皮肤反应","source_version":"2018","source_section":"","source_url":"https://ascopubs.org/doi/abs/10.1200/JCO.2017.77.6385","evidence_summary":"复药决策取决于毒性类型及严重性，不只是症状是否消退。"},"evidence":{"sourceTitle":"ASCO：免疫相关不良反应管理指南（2018），严重皮肤反应","sourceVersion":"2018","evidenceSummary":"复药决策取决于毒性类型及严重性，不只是症状是否消退。"}},{"id":"CASE-2CBF15F6-Q4","domain":"疗效评估","prompt":"患者因严重不良反应未行计划中的食管切除。随后PET未再见原食管壁肿块，仍有代谢摄取，报告考虑治疗后改变。在决定后续局部管理前，最合理的评估方向是？","context":"当前教学复盘：2021年5月：未能按原计划行食管切除 · 2021年5月：未能按原计划行食管切除","options":["将残余摄取视为存活肿瘤，依据PET结果启动挽救手术","结合内镜取样及必要的超声内镜，综合判断局部残留","将肿块消失视为病理缓解，依据PET结果结束局部评估","结合一次肿瘤标志物复查，替代后续内镜组织学评估"],"correctIndex":1,"explanation":"治疗后残余摄取可能与炎症有关，肿块消失也不能证明没有微小残留。局部判断需整合内镜、组织取样及必要的超声内镜等信息，并结合全身复评。未取得切除标本不能以此认定pCR；单次阴性活检同样存在取样局限。","takeaways":["代谢改善、临床完全缓解和病理完全缓解不能互相替代。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"Onkopedia / DGHO","source_title":"Onkopedia：食管癌指南（2024），PET疗效评价边界","source_version":"2024；存档版本","source_section":"","source_url":"https://www.onkopedia-guidelines.info/en/onkopedia/archive/guidelines/esophageal-cancer/version-02122025T174721/%40%40guideline/html/index.html","evidence_summary":"代谢改善、临床完全缓解和病理完全缓解不能互相替代。 补充核对来源：SEOM–GEMCAD–TTD：食管癌指南（更新2025），疗后评估（https://pmc.ncbi.nlm.nih.gov/articles/PMC13099785/）。"},"evidence":{"sourceTitle":"Onkopedia：食管癌指南（2024），PET疗效评价边界","sourceVersion":"2024；存档版本","evidenceSummary":"代谢改善、临床完全缓解和病理完全缓解不能互相替代。 补充核对来源：SEOM–GEMCAD–TTD：食管癌指南（更新2025），疗后评估（https://pmc.ncbi.nlm.nih.gov/articles/PMC13099785/）。"}},{"id":"CASE-2CBF15F6-Q5","domain":"随访管理","prompt":"此后多次随访未发现明确复发，CT仍有轻度食管壁增厚，内镜见黏膜完整但管壁较僵硬。对于继续器官保存管理，哪项安排最合理？","context":"当前教学复盘：2022—2024年：未手术后的连续随访 · 2022—2024年：未手术后的连续随访","options":["以症状复发作为检查触发点，减少无症状时内镜随访","以CT壁厚变化作为主要终点，减少黏膜完整时的取样","持续结合内镜与影像监测，可疑变化时复评挽救治疗","以长期无复发作为治愈依据，转为一般人群常规体检"],"correctIndex":2,"explanation":"未手术后的随访要兼顾局部再生长和远处复发，不能仅依赖症状或CT壁厚。出现可疑变化时应针对性取样，并评估挽救治疗可行性。本例的试验性联合方案及TEN病史具有特殊性，不能据其长期控制推广为所有患者均可省略手术；具体随访间隔需个体化制定。","takeaways":["器官保存是主动监测策略，不是放弃复评与挽救治疗。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"SEOM–GEMCAD–TTD","source_title":"SEOM–GEMCAD–TTD：食管癌指南（更新2025），未手术患者随访原则","source_version":"更新2025","source_section":"","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13099785/","evidence_summary":"器官保存是主动监测策略，不是放弃复评与挽救治疗。"},"evidence":{"sourceTitle":"SEOM–GEMCAD–TTD：食管癌指南（更新2025），未手术患者随访原则","sourceVersion":"更新2025","evidenceSummary":"器官保存是主动监测策略，不是放弃复评与挽救治疗。"}}]},{"id":"CASE-9088ED9B","cancerType":"胃食管结合部腺癌","category":"GEJ腺癌","demoOnly":true,"shortTitle":"GEJ腺癌pCR后复发与双阳性标志物决策","title":"GEJ腺癌pCR后复发与双阳性标志物决策","subtitle":"分期病灶核实、pCR后辅助证据、复发后PD-L1与CLDN18.2治疗依据","doctor":"","hospital":"","minutes":0,"difficulty":"进阶","color":"violet","image":"./assets/cases/gej-adenocarcinoma-home.png","imageAlt":"GEJ腺癌病例主题图","source":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/jyfnUj5CplBd6QLSNVlr5Q/sbmGXu7yTHCLDpQZIAfzMwzHpxBFyPsJ.png","contentImages":[{"src":"./assets/case-content/CASE-9088ED9B.png","alt":"表 1. NGS：患者胃食管交界处活检样本中检测到的体细胞变异","sourceUrl":"https://rs-os-lyh-dt-publicread-picture-bosmetadata-prod.liangyihui.net/document/jyfnUj5CplBd6QLSNVlr5Q/sbmGXu7yTHCLDpQZIAfzMwzHpxBFyPsJ.png"}],"summary":[{"label":"患者画像","value":"男性，54岁，ECOG PS 0；因进行性固体食物吞咽困难约3个月就诊。"},{"label":"初始诊断","value":"胃食管结合部中分化腺癌，材料分期cT3N2M0、III期；左腋窝PET异常经活检支持疫苗相关反应性改变。"},{"label":"病理与分子","value":"HER2阴性、pMMR，PD-L1 CPS 5–9，CLDN18.2阳性细胞比例＞75%；染色强度及检测平台未完整提供。"},{"label":"治疗与复发","value":"FOLFOX诱导后接受放化疗及手术，达到ypT0N0；约10个月后肝活检证实复发，接受FOLFOX联合纳武利尤单抗后部分缓解。"},{"label":"核心难点","value":"区分病理残留与pCR人群的辅助证据，核实伴随诊断完整条件，避免跨试验直接排名。"}],"timeline":[{"date":"初诊","title":"原发灶与病理","detail":"内镜发现近梗阻性GEJ病灶，向近端延伸约5 cm；病理为中分化腺癌。"},{"date":"初始分期","title":"腋窝异常病灶核实","detail":"CT、超声内镜及PET用于分期；左腋窝高摄取病灶活检提示疫苗相关反应性改变，原病例记录cT3N2M0。"},{"date":"治疗前","title":"生物标志物评估","detail":"HER2阴性、pMMR，PD-L1 CPS 5–9、CLDN18.2阳性比例＞75%；摘要未记载膜染色强度。"},{"date":"术前治疗","title":"诱导化疗及放化疗","detail":"接受3周期FOLFOX诱导化疗，再接受以FOLFOX为基础的同步放化疗；PET报告代谢完全缓解。"},{"date":"手术后","title":"病理完全缓解","detail":"接受微创食管切除术，切除标本ypT0N0，19枚淋巴结均无肿瘤。"},{"date":"术后观察","title":"未给予辅助纳武利尤单抗","detail":"病例采用随访；CheckMate 577针对术后病理残留人群，不能直接据其为本例pCR确立常规辅助获益。"},{"date":"术后约10个月","title":"转移性复发确认","detail":"发现肺部多发结节及肝脏新病灶，肝活检证实GEJ腺癌转移；复核CLDN18.2比例及PD-L1 CPS，NGS检出ERBB3、PIK3CA改变。"},{"date":"复发治疗5周期后","title":"联合治疗获益","detail":"FOLFOX联合纳武利尤单抗后部分缓解，生活质量及工作状态良好；摘要未提供更长期结局。"}],"questions":[{"id":"CASE-9088ED9B-Q1","domain":"治疗决策","prompt":"54岁男性，GEJ腺癌初步分期cT3N2M0。PET发现左腋窝淋巴结摄取增高，活检提示与疫苗接种相关的反应性改变。仅针对这一腋窝病灶，下列哪项解释最合理？","context":"当前教学复盘：初始分期：腋窝PET阳性病灶核实 · 初始分期：腋窝PET阳性病灶核实","options":["代谢增高更支持肿瘤转移，应据此按远处转移处理","现有病理支持反应性改变，不宜仅凭PET判定转移","反应性改变支持分期降低，可据此撤销区域淋巴结分期","阴性病理支持免除全身复查，可直接进入局部治疗"],"correctIndex":1,"explanation":"FDG摄取增高并不特异于肿瘤。本例该病灶已有反应性病理解释，不应仅凭PET将其作为转移证据；若影像与取材仍不一致，应复核对应部位及充分性。这一结论只针对腋窝病灶，不能替代其他区域和远处病灶的完整分期。","takeaways":["分期应整合影像与病理，且单个病灶的结论不可无限扩大。"],"reference":{"evidence_type":"指南","doc_id":"","split_index":null,"type":"guideline","authority":"Onkopedia / DGHO","source_title":"Onkopedia：食管癌指南（2024），诊断与分期＋本例病理事实","source_version":"2024；存档版本","source_section":"","source_url":"https://www.onkopedia-guidelines.info/en/onkopedia/archive/guidelines/esophageal-cancer/version-02122025T174721/%40%40guideline/html/index.html","evidence_summary":"分期应整合影像与病理，且单个病灶的结论不可无限扩大。"},"evidence":{"sourceTitle":"Onkopedia：食管癌指南（2024），诊断与分期＋本例病理事实","sourceVersion":"2024；存档版本","evidenceSummary":"分期应整合影像与病理，且单个病灶的结论不可无限扩大。"}},{"id":"CASE-9088ED9B-Q2","domain":"治疗决策","prompt":"患者完成新辅助放化疗及手术，切除标本达到pCR（ypT0N0），19枚淋巴结均无肿瘤。若仅依据CheckMate 577决定是否给予辅助纳武利尤单抗，最准确的结论是？","context":"当前教学复盘：新辅助放化疗及手术后：ypT0N0 · 新辅助放化疗及手术后：ypT0N0","options":["基线属局部晚期人群，足以按该研究支持常规辅助","治疗前存在淋巴结受累，足以按残留病变人群处理","术前PD-L1呈阳性表达，足以替代残留病变入组要求","术后未发现残留病变，不在该研究直接验证的人群内"],"correctIndex":3,"explanation":"CheckMate 577纳入的是新辅助放化疗后R0切除、仍有病理残留的患者，未纳入pCR患者。不能仅依据该研究为ypT0N0患者确立常规辅助纳武利尤单抗的获益；这也不等于证明pCR患者在任何情境下均不能接受免疫治疗。","takeaways":["辅助治疗证据的关键边界是术后病理残留，而非基线分期。"],"reference":{"evidence_type":"临床研究","doc_id":"","split_index":null,"type":"journal","authority":"相应研究组","source_title":"CheckMate 577原始研究，NEJM（2021）","source_version":"2021","source_section":"","source_url":"https://www.nejm.org/doi/full/10.1056/NEJMoa2032125","evidence_summary":"辅助治疗证据的关键边界是术后病理残留，而非基线分期。"},"evidence":{"sourceTitle":"CheckMate 577原始研究，NEJM（2021）","sourceVersion":"2021","evidenceSummary":"辅助治疗证据的关键边界是术后病理残留，而非基线分期。"}},{"id":"CASE-9088ED9B-Q3","domain":"治疗决策","prompt":"患者复发后准备开始转移阶段的一线治疗，HER2阴性、pMMR、PD-L1 CPS为5–9，同时CLDN18.2阳性。依据CheckMate 649，下列哪项最直接支持讨论纳武利尤单抗联合含铂化疗？","context":"当前教学复盘：术后约10个月：肝活检证实转移性复发 · 术后约10个月：肝活检证实转移性复发","options":["HER2阴性且CPS≥5，与研究主要疗效分析人群相符","pMMR且既往达到pCR，提示免疫单药可替代联合化疗","CLDN18.2表达阳性，提示该研究的免疫疗效更为显著","复发前无辅助免疫治疗，提示无需再评估化疗适用性"],"correctIndex":0,"explanation":"CheckMate 649在HER2非阳性晚期胃/GEJ/食管腺癌中评估纳武利尤单抗联合化疗，CPS≥5是主要疗效分析人群。本例提供了匹配依据；是否复用既往化疗仍需考虑停药间隔及耐受性。pMMR不排除联合免疫获益，CLDN18.2则属于另一治疗方向的标志物。","takeaways":["把药物获益与对应的研究人群匹配，不混用不同靶点。"],"reference":{"evidence_type":"临床研究","doc_id":"","split_index":null,"type":"journal","authority":"相应研究组","source_title":"CheckMate 649原始研究，Lancet（2021）","source_version":"2021","source_section":"","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8436782/","evidence_summary":"把药物获益与对应的研究人群匹配，不混用不同靶点。"},"evidence":{"sourceTitle":"CheckMate 649原始研究，Lancet（2021）","sourceVersion":"2021","evidenceSummary":"把药物获益与对应的研究人群匹配，不混用不同靶点。"}},{"id":"CASE-9088ED9B-Q4","domain":"治疗决策","prompt":"病例摘要仅记载“CLDN18.2阳性细胞比例＞75%”，未列染色强度。若参照SPOTLIGHT及FDA相应标签评估佐妥昔单抗的检测条件，首先应向病理科核实哪项信息？","context":"当前教学复盘：复发后双阳性病例的靶向治疗评估 · 复发后双阳性病例的靶向治疗评估","options":["是否存在CLDN18基因扩增，以及拷贝数达到何种阈值","是否存在CLDN18基因融合，以及融合伴侣属于何种类型","是否为合规检测的中至强膜染色，以及对应阳性细胞比例","是否同时存在HER2蛋白高表达，以及两者是否同区域分布"],"correctIndex":2,"explanation":"相应试验及FDA标签将阳性定义为至少75%的肿瘤细胞呈中至强膜染色，并有规定的检测要求。仅有阳性比例不足以确认完整条件；应核对原始报告，而不是假定强度已达标。题目讨论的是研究/标签检测标准，不替代所在地适应证核查。","takeaways":["伴随诊断阈值同时包含染色部位、强度、比例和方法。"],"reference":{"evidence_type":"药品说明书","doc_id":"","split_index":null,"type":"drug_label","authority":"FDA","source_title":"Table of Pharmacogenomic Biomarkers in Drug Labeling — Zolbetuximab-clzb / VYLOY","source_version":"汇编更新2025-12；所引标签2024-10-18","source_section":"第341页；2.1 Patient Selection；14 Clinical Studies","source_url":"https://www.fda.gov/media/124784/download?attachment=","evidence_summary":"FDA汇编所引VYLOY标签要求至少75%肿瘤细胞呈中至强膜染色，并采用相应获批检测；单有阳性比例不足以确认完整条件。"},"evidence":{"sourceTitle":"Table of Pharmacogenomic Biomarkers in Drug Labeling — Zolbetuximab-clzb / VYLOY","sourceVersion":"汇编更新2025-12；所引标签2024-10-18","evidenceSummary":"FDA汇编所引VYLOY标签要求至少75%肿瘤细胞呈中至强膜染色，并采用相应获批检测；单有阳性比例不足以确认完整条件。"}},{"id":"CASE-9088ED9B-Q5","domain":"治疗决策","prompt":"MDT讨论本例双阳性患者的治疗证据。若仅比较CheckMate 649与SPOTLIGHT各自公布的风险比，能否据此认定免疫联合化疗或CLDN18.2靶向联合化疗对本例更优？","context":"当前教学复盘：PD-L1与CLDN18.2双阳性的证据讨论 · PD-L1与CLDN18.2双阳性的证据讨论","options":["可按两项研究OS风险比的大小，排序两方案的优先级","不宜直接比较，入组筛选与对照条件不同会影响结果","可按两项研究PFS风险比的大小，排序两方案的优先级","可按两项研究治疗组中位生存，排序两方案的优先级"],"correctIndex":1,"explanation":"两项研究并非两方案之间的随机头对头比较，生物标志物筛选、患者构成及研究条件不同。直接比较风险比或中位生存容易混入研究间差异。对本例应分别核对适用证据，再结合毒性、既往治疗、可及性和患者偏好讨论，不能用简单数值排名代替决策。","takeaways":["各自优于化疗，不等于两种联合方案之间已分出优劣。"],"reference":{"evidence_type":"临床研究","doc_id":"","split_index":null,"type":"journal","authority":"相应研究组","source_title":"CheckMate 649：研究设计与入组人群","source_version":"2021","source_section":"","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8436782/","evidence_summary":"各自优于化疗，不等于两种联合方案之间已分出优劣。 补充核对来源：FDA：SPOTLIGHT/GLOW研究概览（https://www.fda.gov/drugs/drug-approvals-and-databases/drug-trials-snapshots-vyloy）。"},"evidence":{"sourceTitle":"CheckMate 649：研究设计与入组人群","sourceVersion":"2021","evidenceSummary":"各自优于化疗，不等于两种联合方案之间已分出优劣。 补充核对来源：FDA：SPOTLIGHT/GLOW研究概览（https://www.fda.gov/drugs/drug-approvals-and-databases/drug-trials-snapshots-vyloy）。"}}]}];